# The HHS package is embedded so this file can be deployed by itself.
def _install_embedded_wnba_hhs() -> None:
    import types as _types
    import zlib as _zlib

    _payloads = {'identity': '', 'schema': '', 'storage': '', 'engine': '', 'evaluation': '', 'snapshots': '', '__init__': ''}
    _package = _types.ModuleType("wnba_hhs")
    _package.__file__ = "<embedded wnba_hhs>"
    _package.__package__ = "wnba_hhs"
    _package.__path__ = []
    sys.modules["wnba_hhs"] = _package

    for _name in ('identity', 'schema', 'storage', 'engine', 'evaluation', 'snapshots'):
        _full_name = f"wnba_hhs.{_name}"
        _module = _types.ModuleType(_full_name)
        _module.__file__ = f"<embedded {_full_name}>"
        _module.__package__ = "wnba_hhs"
        sys.modules[_full_name] = _module
        _source = _zlib.decompress(base64.b64decode(_payloads[_name])).decode("utf-8")
        exec(compile(_source, _module.__file__, "exec"), _module.__dict__)

    _init_source = _zlib.decompress(base64.b64decode(_payloads["__init__"])).decode("utf-8")
    exec(compile(_init_source, _package.__file__, "exec"), _package.__dict__)


_install_embedded_wnba_hhs()

