# -----------------------------------------------------------------------------
# Grouped Player Cards Board (single-player card with PTS/REB/AST/PRA rows)
# -----------------------------------------------------------------------------

def apply_saved_tracking_status(df: pd.DataFrame) -> pd.DataFrame:
    """Mark board rows that were saved with Save Before.

    TRACKED is a display state, not a model recommendation. It means the exact
    player/market/line has been saved and is waiting to be graded. Rows that
    passed the official gate at save time display OFFICIAL; all other saved
    real-line rows display TRACK.
    """
    if df is None or df.empty:
        return df
    out = df.copy()
    out["Tracking Status"] = ""
    try:
        raw = load_json(OFFICIAL_LOG, [])
        if not isinstance(raw, list) or not raw:
            return out
        log = pd.DataFrame(raw)
        if log.empty:
            return out
        # Only pending/current before-game records should light up the cards.
        if "Result" in log.columns:
            log = log[log["Result"].astype(str).str.upper().isin(["PENDING", "", "NAN", "NONE"])].copy()
        if log.empty:
            return out
        log["_name"] = log.get("Player", "").map(normalize_name)
        log["_market"] = log.get("Market", "").astype(str).str.upper().str.strip()
        log["_line"] = pd.to_numeric(log.get("Line"), errors="coerce").round(2)
        log["_status"] = np.where(
            log.get("SnapshotType", "").astype(str).str.upper().eq("OFFICIAL_GATE"),
            "OFFICIAL", "TRACK"
        )
        # Keep the latest state for duplicate historical saves.
        if "SavedAt" in log.columns:
            log = log.sort_values("SavedAt").drop_duplicates(["_name", "_market", "_line"], keep="last")
        else:
            log = log.drop_duplicates(["_name", "_market", "_line"], keep="last")
        idx = {(r["_name"], r["_market"], r["_line"]): r["_status"] for _, r in log.iterrows() if pd.notna(r["_line"])}
        names = out.get("Player", pd.Series(index=out.index, dtype=str)).map(normalize_name)
        mkts = out.get("Market", pd.Series(index=out.index, dtype=str)).astype(str).str.upper().str.strip()
        lines = pd.to_numeric(out.get("Line"), errors="coerce").round(2)
        out["Tracking Status"] = [idx.get((n, m, l), "") if pd.notna(l) else "" for n, m, l in zip(names, mkts, lines)]
    except Exception:
        pass
    return out

def _fmt_num_compact(x, dec=1, default="—"):
    try:
        v = safe_float(x, np.nan)
        if pd.isna(v):
            return default
        return f"{v:.{dec}f}"
    except Exception:
        return default


def _grouped_market_html(r: pd.Series) -> str:
    market = str(r.get("Market", "PROP")).upper()
    proj = _fmt_num_compact(r.get("Projection"), 1)
    line = _fmt_num_compact(r.get("Line"), 1)
    edge_v = safe_float(r.get("Edge"), np.nan)
    edge = _fmt_num_compact(edge_v, 1)
    lean = str(r.get("Lean", "TRACK")).upper()
    official = str(r.get("Official", ""))
    side_txt = "OVER" if "OVER" in f"{lean} {official}" else "UNDER" if "UNDER" in f"{lean} {official}" else "TRACK"
    side_cls = "over" if side_txt == "OVER" else "under" if side_txt == "UNDER" else "track"
    overp = safe_float(r.get("Over %"), np.nan)
    underp = safe_float(r.get("Under %"), np.nan)
    fill = overp if pd.notna(overp) else (100-underp if pd.notna(underp) else 50)
    fill = max(0, min(100, fill))
    conf = _fmt_num_compact(r.get("Official Play Score"), 0)
    tier = str(r.get("Tier", ""))
    tracking_status = str(r.get("Tracking Status", "") or "").upper()
    if str(official).upper().startswith("LONG STRONG"):
        rec_badge = "LONG"
    elif str(official).upper().startswith("STRONG"):
        rec_badge = "STRONG"
    elif str(official).upper().startswith("LEAN"):
        rec_badge = "LEAN"
    else:
        rec_badge = tracking_status if tracking_status in {"TRACK", "OFFICIAL"} else tier
    track_badge = rec_badge
    track_cls = "official" if tracking_status == "OFFICIAL" else "tracked" if tracking_status == "TRACK" else ""
    vol = str(r.get("Volatility", "NA"))
    edge_cls = "pos" if pd.notna(edge_v) and edge_v > 0 else "neg" if pd.notna(edge_v) and edge_v < 0 else "flat"
    source = html.escape(str(r.get("Source", "Unknown") or "Unknown"))
    opening = _fmt_num_compact(r.get("Opening Line"), 1)
    clv = _fmt_num_compact(r.get("CLV"), 1)
    line_age = _fmt_num_compact(r.get("Line Age Minutes"), 0)
    line_meta = f"Source {source}"
    if opening != "—":
        line_meta += f" · Open {opening}"
    if clv != "—":
        line_meta += f" · CLV {clv}"
    if line_age != "—":
        line_meta += f" · Age {line_age}m"
    return f"""
      <div class='owp-market-row owp-mkt-{market.lower()}'>
        <div class='owp-market-head'>
          <span class='owp-market-name'>{market}</span>
          <span class='owp-market-vol'>{vol}</span>
          <span class='owp-market-conf {side_cls}'>HIGH {conf}%</span>
          <span class='owp-market-side {side_cls}'>{side_txt}</span>
        </div>
        <div class='owp-market-values'>
          <div class='owp-value-box'><small>Projection</small><b>{proj}</b></div>
          <div class='owp-value-box line'><small>Line</small><b>{line}</b></div>
          <div class='owp-value-box'><small>Edge</small><b class='{edge_cls}'>{edge}</b></div>
          <div class='owp-value-box pick'><small>Pick</small><b>{side_txt}</b><span>{track_badge}</span></div>
        </div>
        <div class='owp-line-meta'>{line_meta}</div>
        <div class='owp-prob-track owp-market-track'><div class='owp-prob-fill' style='width:{fill:.0f}%'></div></div>
        <div class='owp-market-sub'><span>OVER {_fmt_num_compact(overp,0)}%</span><span>UNDER {_fmt_num_compact(underp,0)}%</span></div>
      </div>
    """


def _market_why_df(r: pd.Series) -> pd.DataFrame:
    rows = []
    for label, col in [
        ("Projection reason", "Projection Explanation"),
        ("Recent / hit-rate support", "Hit Rate Context"),
        ("Recent support", "Recent Support"),
        ("Veteran / capability", "Veteran Capability"),
        ("Game script", "WNBA ML Game Script"),
        ("Game script note", "WNBA ML Game Script Note"),
        ("Risk / no-bet flags", "No-Bet Risk Flags"),
        ("Pass / gate note", "PASS Reason"),
        ("Winning gate", "Winning Gate Note"),
        ("Line selection", "Line Selection"),
        ("UD line kind", "UD Line Kind"),
        ("Projection integrity", "Projection Integrity Note"),
    ]:
        val = str(r.get(col, "") or "").strip()
        if val and val.lower() not in {"nan", "none"}:
            rows.append({"Field": label, "Value": re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", val)).strip()})
    if not rows:
        rows.append({"Field": "Details", "Value": "No extra notes available for this market."})
    return pd.DataFrame(rows)


def _team_logo_html(team: Any, extra_cls: str = "") -> str:
    abbr = html.escape(team_abbr_for_logo(team))
    src = html.escape(get_team_logo_src(team))
    if src:
        return (
            f"<span class='owp-team-logo {extra_cls}'>"
            f"<img class='owp-team-logo-img' src='{src}' alt='{abbr}' "
            f"onerror=\"this.style.display='none';this.nextElementSibling.style.display='inline'\">"
            f"<span class='owp-team-logo-text' style='display:none'>{abbr}</span>"
            f"</span>"
        )
    return f"<span class='owp-team-logo {extra_cls}'><span class='owp-team-logo-text'>{abbr}</span></span>"


def render_grouped_player_card(player_df: pd.DataFrame):
    if player_df is None or player_df.empty:
        return
    # Sort markets in the normal board order.
    order = {m:i for i,m in enumerate(MARKETS)}
    player_df = player_df.copy()
    player_df["_market_order"] = player_df.get("Market", "").astype(str).str.upper().map(order).fillna(99)
    player_df = player_df.sort_values(["_market_order"])
    first = player_df.iloc[0]
    player = str(first.get("Player", "Player"))
    team = str(first.get("Team", ""))
    opp = str(first.get("Opponent", ""))
    matchup = str(first.get("Matchup", "") or first.get("Projection Matchup Used", "") or team)
    pos = str(first.get("PositionGroup", "Role"))
    source_count = ", ".join(sorted(set(player_df.get("Source", pd.Series(dtype=str)).astype(str).replace("nan", "").tolist())))
    role = str(first.get("FallbackLineupRole", first.get("Minutes Safety", "NA")))
    min_proj = _fmt_num_compact(player_df.get("MIN Proj", pd.Series([np.nan])).max(), 1)
    data_score = _fmt_num_compact(player_df.get("Data Score", pd.Series([np.nan])).max(), 0)
    market_html = "".join(_grouped_market_html(r) for _, r in player_df.iterrows())
    tracked_n = int(player_df.get("Tracking Status", pd.Series(dtype=str)).astype(str).str.upper().isin(["TRACK", "OFFICIAL"]).sum())
    tracking_pill = f"<span class='owp-pill owp-pill-track'>TRACKED {tracked_n}/{len(player_df)}</span>" if tracked_n else ""
    line_vals = pd.to_numeric(player_df.get("Line", pd.Series(np.nan, index=player_df.index)), errors="coerce")
    source_vals = player_df.get("Source", pd.Series("", index=player_df.index)).astype(str).str.upper()
    bad_line_n = int((line_vals.isna() | line_vals.le(0) | source_vals.str.contains("NO LINE|BASELINE", na=False)).sum())
    line_warn = f"<span class='owp-pill owp-pill-warn'>CHECK LINES {bad_line_n}</span>" if bad_line_n else ""
    team_logo = _team_logo_html(team)
    opp_logo = _team_logo_html(opp, "owp-opp-logo")
    st.markdown(f"""
    <div class='owp-group-card'>
      <div class='owp-group-top'>
        <div class='owp-player-wrap'>
          <div class='owp-logo-row'>{team_logo}<span class='owp-vs'>vs</span>{opp_logo}</div>
          <div class='owp-player'>{player}</div>
          <div class='owp-match'>{matchup} <span class='owp-muted'>| {team} | {pos}</span></div>
          <span class='owp-pill owp-pill-source'>{source_count or 'Lines'}</span>
          <span class='owp-pill owp-pill-role'>Lineup/Role {role}</span>
          <span class='owp-pill owp-pill-score'>Data {data_score}/100</span>
          {tracking_pill}
          {line_warn}
        </div>
      </div>
      {market_html}
    </div>
    """, unsafe_allow_html=True)
    for _, rr in player_df.iterrows():
        m = str(rr.get("Market", "PROP")).upper()
        lean = str(rr.get("Lean", "TRACK")).upper()
        proj = _fmt_num_compact(rr.get("Projection"), 1)
        line = _fmt_num_compact(rr.get("Line"), 1)
        with st.expander(f"Why — {player} {m}: proj {proj} vs line {line} ({lean})", expanded=False):
            st.dataframe(_market_why_df(rr), use_container_width=True, hide_index=True)
    with st.expander(f"Advanced details — {player} all markets", expanded=False):
        show_cols = [c for c in ["Market","Projection","Line","Edge","Lean","Over %","Under %","Official Play Score","Tier","Source","Line Selection","UD Candidate Order","UD Base Score","UD Line Kind","UD Two Sided","Opening Line","CLV","Line Age Minutes","Line Snapshot Count","Freshness Status","Opponent","HomeAway","Matchup","Raw","Projection Explanation"] if c in player_df.columns]
        st.dataframe(player_df[show_cols], use_container_width=True, hide_index=True)




def grouped_board_table_view(proj_df: pd.DataFrame) -> pd.DataFrame:
    """Compact grouped table for speed: one row per player/market, sorted by player and market."""
    if proj_df is None or proj_df.empty:
        return pd.DataFrame()
    df = proj_df.copy()
    order = {m:i for i,m in enumerate(MARKETS)}
    df["_market_order"] = df.get("Market", "").astype(str).str.upper().map(order).fillna(99)
    # Keep only useful board columns so this loads much faster than rendering all cards.
    keep = [c for c in [
        "Player", "Team", "Opponent", "Matchup", "Market", "Projection", "Line", "Edge",
        "Lean", "Over %", "Under %", "Official Play Score", "Tier", "Volatility",
        "MIN Proj", "FallbackLineupRole", "Tracking Status", "Source"
    ] if c in df.columns]
    if not keep:
        return df
    out = df.sort_values(["Player", "_market_order"], na_position="last")[keep].copy()
    for c in ["Projection", "Line", "Edge", "Over %", "Under %", "Official Play Score", "MIN Proj"]:
        if c in out.columns:
            out[c] = pd.to_numeric(out[c], errors="coerce").round(2)
    return out


def render_fast_projection_rows(proj_df: pd.DataFrame) -> None:
    """Compact mobile-first WNBA cards with team logo + role/context support."""
    if proj_df is None or proj_df.empty:
        st.info("No projection rows to show.")
        return
    order = {m: i for i, m in enumerate(MARKETS)}
    view = proj_df.copy()
    view["_market_order"] = view.get("Market", "").astype(str).str.upper().map(order).fillna(99)
    view = view.sort_values(["Player", "_market_order"], kind="stable")

    rows = []
    for _, r in view.iterrows():
        player = html.escape(str(r.get("Player", "Player")))
        team_raw = str(r.get("Team", ""))
        opp_raw = str(r.get("Opponent", ""))
        team = html.escape(team_abbr_for_logo(team_raw))
        opponent = html.escape(team_abbr_for_logo(opp_raw)) if opp_raw else ""
        logo_src = html.escape(get_team_logo_src(team_raw))
        logo_html = (
            f"<span class='owp-fast-logo'><img src='{logo_src}' alt='{team}'><em>{team}</em></span>"
            if logo_src else f"<span class='owp-fast-logo'><em>{team}</em></span>"
        )

        home_away = str(r.get("HomeAway", "")).strip().upper()
        venue_tag = "AWAY" if home_away.startswith("A") else "HOME" if home_away.startswith("H") else ""
        matchup = f"{team} {('@' if venue_tag == 'AWAY' else 'vs')} {opponent}" if opponent else team

        market = html.escape(str(r.get("Market", ""))).upper()
        projection = safe_float(r.get("Projection"), np.nan)
        line = safe_float(r.get("Line"), np.nan)
        edge = projection - line if pd.notna(projection) and pd.notna(line) else np.nan
        lean = str(r.get("Lean", "")).upper()
        if lean not in {"OVER", "UNDER"} and pd.notna(edge):
            lean = "OVER" if edge > 0 else "UNDER" if edge < 0 else "PASS"
        side_prob = safe_float(r.get("Over %" if lean == "OVER" else "Under %"), np.nan)
        side_class = "over" if lean == "OVER" else "under" if lean == "UNDER" else "pass"
        edge_class = "positive" if pd.notna(edge) and edge > 0 else "negative" if pd.notna(edge) and edge < 0 else "flat"

        proj_text = "—" if pd.isna(projection) else f"{projection:.1f}".rstrip("0").rstrip(".")
        line_text = "—" if pd.isna(line) else f"{line:.1f}".rstrip("0").rstrip(".")
        edge_text = "—" if pd.isna(edge) else f"{edge:+.1f}"
        prob_text = "—" if pd.isna(side_prob) else f"{side_prob:.0f}%"

        min_proj = safe_float(r.get("MIN Proj"), safe_float(r.get("Projected Minutes"), np.nan))
        scoring_role = str(r.get("Elite Scoring Role", r.get("Scoring Role", "")) or "").replace("_", " ").upper()
        rebound_role = str(r.get("Elite Rebound Role", r.get("Rebound Role", "")) or "").replace("_", " ").upper()
        creation_role = str(r.get("Elite Creation Role", r.get("Creation Role", "")) or "").replace("_", " ").upper()
        if market == "PTS":
            role = scoring_role
            share = safe_float(r.get("Elite Team PTS Share %"), safe_float(r.get("Team PTS Share %"), np.nan))
            share_label = "PTS SHARE"
        elif market == "REB":
            role = rebound_role
            share = safe_float(r.get("Elite Team REB Share %"), safe_float(r.get("Team REB Share %"), np.nan))
            share_label = "REB SHARE"
        elif market == "AST":
            role = creation_role
            share = safe_float(r.get("Elite Team AST Share %"), safe_float(r.get("Team AST Share %"), np.nan))
            share_label = "AST SHARE"
        else:
            role = " / ".join([x for x in [scoring_role, rebound_role, creation_role] if x][:2])
            share = np.nan
            share_label = "ROLE"
        if not role:
            role = str(r.get("FallbackLineupRole", "ROLE N/A") or "ROLE N/A").replace("_", " ").upper()

        role_short = html.escape(role[:28])
        min_text = "—" if pd.isna(min_proj) else f"{min_proj:.1f}"
        share_text = "—" if pd.isna(share) else f"{share:.0f}%"
        official_score = safe_float(r.get("Official Play Score"), safe_float(r.get("Elite Rank Score"), np.nan))
        status = str(r.get("Tier", r.get("Elite Status", "")) or "").upper()
        score_text = prob_text if pd.isna(official_score) else f"{official_score:.0f}"

        rows.append(
            "<div class='owp-fast-card'>"
            "<div class='owp-fast-main'>"
            f"<div class='owp-fast-player'>{logo_html}<div><b>{player}</b><span>{matchup}{(' · ' + venue_tag) if venue_tag else ''}</span></div></div>"
            f"<div class='owp-fast-market'><small>MARKET</small><b>{market}</b></div>"
            f"<div class='owp-fast-line'><small>LINE</small><b>{html.escape(lean or 'PASS')} {line_text}</b></div>"
            f"<div class='owp-fast-likely {side_class}'><small>LIKELY</small><b>{prob_text}</b><span>{html.escape(status[:18]) if status else 'MODEL'}</span></div>"
            "</div>"
            "<div class='owp-fast-support'>"
            f"<div><small>PROJ</small><b>{proj_text}</b></div>"
            f"<div><small>EDGE</small><b class='{edge_class}'>{edge_text}</b></div>"
            f"<div><small>MIN</small><b>{min_text}</b></div>"
            f"<div class='owp-fast-role'><small>ROLE</small><b>{role_short}</b></div>"
            f"<div><small>{share_label}</small><b>{share_text}</b></div>"
            f"<div><small>SCORE</small><b>{score_text}</b></div>"
            "</div></div>"
        )

    markup = '''
    <style>
    .owp-fast-board2{width:100%;display:flex;flex-direction:column;gap:10px;color:#e7edf5}
    .owp-fast-card{background:linear-gradient(180deg,#07131f,#091521);border:1px solid rgba(96,165,250,.28);border-radius:16px;padding:10px 12px;box-sizing:border-box;min-height:128px}
    .owp-fast-main{display:grid;grid-template-columns:minmax(220px,2.25fr) .7fr .95fr .8fr;gap:8px;align-items:stretch}
    .owp-fast-player,.owp-fast-market,.owp-fast-line,.owp-fast-likely{background:rgba(7,16,26,.72);border:1px solid rgba(148,163,184,.13);border-radius:11px;min-height:48px;box-sizing:border-box}
    .owp-fast-player{display:flex;align-items:center;gap:9px;padding:6px 9px;min-width:0}.owp-fast-player>div{min-width:0}
    .owp-fast-player b{display:block;font-size:.94rem;color:#f8fafc;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.owp-fast-player span{display:block;color:#64748b;font-size:.61rem;margin-top:2px;text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
    .owp-fast-logo{width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;overflow:hidden;flex:0 0 auto;background:#0d1b2a;border:1px solid rgba(96,165,250,.32)}.owp-fast-logo img{width:100%;height:100%;object-fit:contain;padding:3px;box-sizing:border-box}.owp-fast-logo em{font-style:normal;font-size:.58rem;font-weight:1000;color:#facc15}
    .owp-fast-market,.owp-fast-line,.owp-fast-likely{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:5px;text-align:center}
    .owp-fast-main small,.owp-fast-support small{color:#64748b;font-size:.50rem;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.owp-fast-main b{font-size:.75rem;color:#f8fafc}.owp-fast-market b{color:#f472b6}.owp-fast-likely.over b{color:#4ade80}.owp-fast-likely.under b{color:#60a5fa}.owp-fast-likely.pass b{color:#94a3b8}.owp-fast-likely span{font-size:.48rem;color:#facc15;font-weight:900;margin-top:1px}
    .owp-fast-support{display:grid;grid-template-columns:.65fr .65fr .65fr 1.65fr .8fr .65fr;gap:7px;margin-top:7px}.owp-fast-support>div{background:rgba(8,20,32,.62);border:1px solid rgba(148,163,184,.10);border-radius:9px;padding:6px 8px;min-height:38px;box-sizing:border-box;display:flex;flex-direction:column;justify-content:center}.owp-fast-support b{font-size:.75rem;color:#e2e8f0;line-height:1.05;margin-top:2px}.owp-fast-support b.positive{color:#4ade80}.owp-fast-support b.negative{color:#fb7185}.owp-fast-support b.flat{color:#94a3b8}.owp-fast-role b{font-size:.62rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#c4b5fd}
    @media(max-width:700px){.owp-fast-card{min-height:0;padding:8px;border-radius:14px}.owp-fast-main{grid-template-columns:minmax(0,2.1fr) .58fr .8fr .64fr;gap:5px}.owp-fast-player,.owp-fast-market,.owp-fast-line,.owp-fast-likely{min-height:43px;border-radius:9px}.owp-fast-player{gap:6px;padding:5px 6px}.owp-fast-logo{width:29px;height:29px}.owp-fast-player b{font-size:.76rem}.owp-fast-player span{font-size:.49rem}.owp-fast-main b{font-size:.61rem}.owp-fast-main small,.owp-fast-support small{font-size:.42rem}.owp-fast-likely span{font-size:.40rem}.owp-fast-support{grid-template-columns:.58fr .58fr .55fr 1.45fr .72fr .55fr;gap:4px;margin-top:5px}.owp-fast-support>div{padding:5px;min-height:34px;border-radius:8px}.owp-fast-support b{font-size:.60rem}.owp-fast-role b{font-size:.49rem}.owp-fast-board2{gap:7px}}
    </style>
    <div class='owp-fast-board2'>
    ''' + "".join(rows) + "</div>"
    st.markdown(markup, unsafe_allow_html=True)

def render_grouped_table_or_cards(proj_df: pd.DataFrame, mode: str, key_prefix: str, default_cards: bool = True) -> pd.DataFrame:
    """Fast display switcher. Table mode avoids rendering dozens of heavy HTML cards."""
    if proj_df is None or proj_df.empty:
        st.info("No rows to show.")
        return pd.DataFrame()
    search = st.text_input("Search player", key=f"{key_prefix}_search")
    official_only = st.toggle("Official / strong signals only", value=False, key=f"{key_prefix}_official")
    view_df = apply_saved_tracking_status(proj_df.copy())
    if search and "Player" in view_df.columns:
        view_df = view_df[view_df["Player"].astype(str).str.contains(search, case=False, na=False)]
    if official_only and "Official" in view_df.columns:
        view_df = view_df[view_df["Official"].astype(str).str.contains("OVER|UNDER", na=False)]

    c1,c2,c3,c4 = st.columns(4)
    c1.metric("Players", view_df["Player"].nunique() if "Player" in view_df.columns else 0)
    c2.metric("Markets", len(view_df))
    c3.metric("Official plays", int(view_df.get("Official", pd.Series(dtype=str)).astype(str).str.contains("OVER|UNDER", na=False).sum()))
    c4.metric("Avg edge", round(float(pd.to_numeric(view_df.get("Edge", pd.Series(dtype=float)), errors="coerce").abs().mean()), 2) if not view_df.empty else 0)
    with st.expander("Board coverage — teams / matchups / markets", expanded=False):
        if "Matchup" in view_df.columns:
            st.dataframe(view_df["Matchup"].astype(str).replace("", "Unknown").value_counts().rename_axis("Matchup").reset_index(name="Rows"), use_container_width=True, hide_index=True)
        if "Slate Missing From Player Props" in view_df.columns:
            missing_props = str(view_df["Slate Missing From Player Props"].dropna().astype(str).iloc[0]) if len(view_df["Slate Missing From Player Props"].dropna()) else ""
            if missing_props:
                st.warning(f"Schedule has no pulled player props for: {missing_props}. Moneyline can still show those games.")
        if "Team" in view_df.columns:
            st.dataframe(view_df["Team"].astype(str).map(team_abbrev).value_counts().rename_axis("Team").reset_index(name="Rows"), use_container_width=True, hide_index=True)
        if all(c in view_df.columns for c in ["Player", "Team", "Opponent", "Market", "Line", "Source"]):
            st.dataframe(view_df[["Player", "Team", "Opponent", "Matchup", "Market", "Line", "Source"] if "Matchup" in view_df.columns else ["Player", "Team", "Opponent", "Market", "Line", "Source"]].sort_values([c for c in ["Matchup", "Team", "Player", "Market"] if c in view_df.columns]), use_container_width=True, hide_index=True, height=360)

    display_mode = st.radio(
        "View",
        ["Fast table", "Player cards"],
        index=1 if default_cards else 0,
        horizontal=True,
        key=f"{key_prefix}_display_mode",
        help="Fast table loads quickest. Player cards show the full grouped-card view."
    )

    ac1, ac2, ac3 = st.columns([1.2,1.2,1.4])
    with ac1:
        if st.button(f"✅ Save {mode} Official Before", key=f"{key_prefix}_save_before", use_container_width=True):
            n = save_officials(view_df)
            snapshot_n = save_board_snapshot(
                view_df,
                st.session_state.get("wnba_lines_all", pd.DataFrame()),
                mode,
            )
            st.session_state["wnba_prefer_projection_cache_after_refresh"] = False
            st.success(f"Saved {n} tracked plays and {snapshot_n} board rows. {mode} will reload without refreshing.")
    with ac2:
        if st.button(f"📊 Pull Final Results + Grade", key=f"{key_prefix}_grade_after", use_container_width=True):
            n, grade_dbg = pull_final_results_and_grade(mode)
            st.success(f"Pulled final boxscores and graded {n} pending plays for {mode}.")
            if n == 0:
                with st.expander("Why did grading return 0?", expanded=True):
                    st.dataframe(grade_dbg, use_container_width=True, hide_index=True)
    with ac3:
        st.download_button(f"Download {mode} Board CSV", view_df.to_csv(index=False), f"wnba_{mode.lower().replace(' ','_')}_board.csv", "text/csv", key=f"{key_prefix}_download")

    if view_df.empty:
        st.info("No rows after filters.")
        return view_df

    if display_mode == "Fast table":
        render_fast_projection_rows(view_df)
        return view_df

    show_all = st.toggle("Show all player cards", value=True, key=f"{key_prefix}_show_all_cards")
    max_default = min(40, max(10, int(view_df["Player"].nunique() if "Player" in view_df.columns else 40)))
    max_players = len(view_df["Player"].dropna().unique()) if show_all and "Player" in view_df.columns else st.slider("Max player cards", 10, 120, max_default, 5, key=f"{key_prefix}_max_cards")
    sort_df = view_df.copy()
    sort_df["_abs_edge"] = pd.to_numeric(sort_df.get("Edge", np.nan), errors="coerce").abs()
    sort_df["_score"] = pd.to_numeric(sort_df.get("Official Play Score", np.nan), errors="coerce")
    player_order = sort_df.groupby("Player", dropna=False).agg(MaxScore=("_score","max"), MaxEdge=("_abs_edge","max")).reset_index().sort_values(["MaxScore","MaxEdge"], ascending=False)["Player"].head(max_players).tolist()
    for i in range(0, len(player_order), 2):
        cols = st.columns(2)
        for j, player in enumerate(player_order[i:i+2]):
            with cols[j]:
                render_grouped_player_card(view_df[view_df["Player"] == player])
    return view_df



# -----------------------------------------------------------------------------
# Copy / Paste Slate Tracker
# -----------------------------------------------------------------------------
def _slate_side_and_icon(row: pd.Series) -> tuple[str, str]:
    lean = str(row.get("Lean", "")).upper()
    official = str(row.get("Official", "")).upper()
    score = safe_float(row.get("Official Play Score"), 0)
    side_prob = safe_float(row.get("Over %"), 0) if "OVER" in f"{lean} {official}" else safe_float(row.get("Under %"), 0)
    if "OVER" in f"{lean} {official}":
        side = "O"
    elif "UNDER" in f"{lean} {official}":
        side = "U"
    else:
        side = "O" if safe_float(row.get("Edge"), 0) >= 0 else "U"
    if score >= 82 and side_prob >= 64:
        icon = "🔥"
    elif score >= 70 and side_prob >= 58:
        icon = "⚠️"
    else:
        icon = ""
    return side, icon


def _slate_matchup_label(row: pd.Series) -> str:
    matchup = str(row.get("Matchup", "") or row.get("Projection Matchup Used", "")).strip()
    if matchup and matchup.lower() not in {"nan", "none", "unknown"}:
        return matchup.replace(" vs ", " @ ").replace(" VS ", " @ ")
    team = str(row.get("Team", "")).strip().upper()
    opp = str(row.get("Opponent", "")).strip().upper()
    homeaway = str(row.get("HomeAway", "")).upper()
    if team and opp:
        return f"{team} @ {opp}" if homeaway == "AWAY" else f"{opp} @ {team}" if homeaway == "HOME" else f"{team} vs {opp}"
    return team or opp or "WNBA SLATE"


def _historical_build_copy_paste_slate_app120(df: pd.DataFrame, best_only: bool = False, max_rows: int = 0) -> str:
    """Create a clean matchup-grouped tracking slate from every real line."""
    if df is None or df.empty:
        return "No projections available."
    work = df.copy()
    for c in ["Line", "Projection", "Edge", "Official Play Score", "Over %", "Under %", "MIN Proj"]:
        if c in work.columns:
            work[c] = pd.to_numeric(work[c], errors="coerce")
    work = work[work.get("Line", pd.Series(index=work.index, dtype=float)).notna() & work.get("Projection", pd.Series(index=work.index, dtype=float)).notna()].copy()
    if "Source" in work.columns:
        bad = work["Source"].astype(str).str.upper().str.contains("NO LINE|TRACKED ONLY|MISSING", na=False)
        work = work[~bad]
    if work.empty:
        projection_only = df.copy()
        projection_only["Projection"] = pd.to_numeric(projection_only.get("Projection"), errors="coerce")
        projection_only["Line"] = pd.to_numeric(projection_only.get("Line"), errors="coerce")
        projection_only = projection_only[projection_only["Projection"].notna() & projection_only["Line"].isna()].copy()
        if projection_only.empty:
            return "No projections available."
        if best_only:
            return "No betting slate: live sportsbook lines are unavailable. Projection-only rows are PASS."
        projection_only["_matchup"] = projection_only.apply(_slate_matchup_label, axis=1)
        projection_only = projection_only.sort_values(["_matchup", "Player", "Market"], kind="stable")
        blocks = []
        for matchup, group in projection_only.groupby("_matchup", sort=False):
            lines = [f"{matchup} — PROJECTION ONLY / NO LIVE LINES"]
            for _, row in group.iterrows():
                player = str(row.get("Player", "Player"))
                market = str(row.get("Market", "PROP")).upper()
                projection = _fmt_num_compact(row.get("Projection"), 2)
                hhs = _fmt_num_compact(row.get("HHS Projection"), 2)
                hhs_text = f" — HHS {hhs}" if hhs != "—" else ""
                lines.append(f"• {player} — {market} {projection} PROJ{hhs_text} — PASS (NO LINE)")
            blocks.append("\n".join(lines))
        return "\n\n".join(blocks)
    work["_matchup"] = work.apply(_slate_matchup_label, axis=1)
    work["_abs_edge"] = pd.to_numeric(work.get("Edge", 0), errors="coerce").abs()
    work["_score"] = pd.to_numeric(work.get("Official Play Score", 0), errors="coerce").fillna(0)
    if best_only:
        official_mask = work.get("Official", pd.Series(index=work.index, dtype=str)).astype(str).str.contains("OVER|UNDER", case=False, na=False)
        strong = work[official_mask | ((work["_score"] >= 70) & (work["_abs_edge"] >= 1.5))].copy()
        if not strong.empty:
            work = strong
        else:
            work = work.sort_values(["_score", "_abs_edge"], ascending=False).head(12)
    work = work.sort_values(["_matchup", "_score", "_abs_edge"], ascending=[True, False, False])
    if max_rows and max_rows > 0:
        work = work.head(max_rows)
    blocks = []
    for matchup, group in work.groupby("_matchup", sort=False):
        lines = [str(matchup)]
        for _, r in group.iterrows():
            side, icon = _slate_side_and_icon(r)
            player = str(r.get("Player", "Player"))
            market = str(r.get("Market", "PROP")).upper()
            line = _fmt_num_compact(r.get("Line"), 1)
            proj = _fmt_num_compact(r.get("Projection"), 2)
            mins = _fmt_num_compact(r.get("MIN Proj"), 2)
            icon_txt = f"{icon} " if icon else ""
            minute_txt = f" — MIN {mins}" if mins != "—" else ""
            v2_val = safe_float(r.get("PTS V2 Projection"), np.nan) if market == "PTS" else safe_float(r.get("PRA V2 Projection"), np.nan) if market == "PRA" else np.nan
            v2_side = str(r.get("PTS V2 Side", "") or "") if market == "PTS" else ""
            v2_text = f" — V2 {v2_val:.2f}{(' ' + v2_side) if v2_side else ''}" if pd.notna(v2_val) else ""
            lines.append(f"• {player} — {icon_txt}{side} {line} {market} — {proj} LEGACY{v2_text}{minute_txt}")
        blocks.append("\n".join(lines))
    return "\n\n".join(blocks)


def render_slate_tracker(board_df: pd.DataFrame, key_prefix: str = "slate_tracker"):
    st.subheader("Copy/Paste Slate — All WNBA Projections")
    st.caption("Tracking list grouped by matchup. It shows every real-line projection and keeps Best Slate separate from the full board.")
    if board_df is None or board_df.empty:
        st.warning("No projection board cached yet. Refresh Today or All Lines first.")
        return
    render_wnba_ml_system(board_df, key_prefix)
    c1, c2 = st.columns(2)
    with c1:
        best_text = build_copy_paste_slate(board_df, best_only=True)
        st.markdown("#### Best slate")
        st.text_area("Best projections slate", best_text, height=320, key=f"{key_prefix}_best_text")
        st.download_button("Download best slate.txt", best_text, "wnba_best_slate.txt", "text/plain", key=f"{key_prefix}_best_dl")
    with c2:
        all_text = build_copy_paste_slate(board_df, best_only=False)
        st.markdown("#### All projections slate")
        st.text_area("All projections slate", all_text, height=320, key=f"{key_prefix}_all_text")
        st.download_button("Download all projections.txt", all_text, "wnba_all_projections.txt", "text/plain", key=f"{key_prefix}_all_dl")
    st.info("Save Before tracks the real-line rows for grading. The text slate is for copy/paste and quick tracking; it does not replace the saved official log.")


def _team_context_cache_signature() -> str:
    parts = []
    for dataset_key in ["team_season_stats", "team_ranks", "master_features"]:
        path = CACHE_FILES.get(dataset_key)
        try:
            stat = Path(path).stat()
            parts.append(f"{dataset_key}:{stat.st_mtime_ns}:{stat.st_size}")
        except Exception:
            parts.append(f"{dataset_key}:missing")
    return "|".join(parts)


@st.cache_data(ttl=900, show_spinner=False)
def _cached_ml_team_context(signature: str) -> pd.DataFrame:
    try:
        ctx = _strict_team_context_table()
    except Exception:
        ctx = pd.DataFrame()
    if ctx is None or ctx.empty:
        return pd.DataFrame()
    out = ctx.copy()
    for c in ["Pace", "ORtg", "DRtg", "NetRtg"]:
        if c in out.columns:
            out[c] = pd.to_numeric(out[c], errors="coerce")
    out["Team"] = out["Team"].map(_team_key_for_matchup)
    return out.dropna(subset=["Team"]).drop_duplicates("Team", keep="last")


_RUNTIME_TEAM_CONTEXT_SIGNATURE = ""
_RUNTIME_TEAM_CONTEXT = pd.DataFrame()


def _ml_team_context() -> pd.DataFrame:
    # Every prop row for the same slate shares the same team environment. The
    # previous implementation rebuilt and reread this table hundreds of times.
    global _RUNTIME_TEAM_CONTEXT_SIGNATURE, _RUNTIME_TEAM_CONTEXT
    signature = _team_context_cache_signature()
    if signature != _RUNTIME_TEAM_CONTEXT_SIGNATURE:
        _RUNTIME_TEAM_CONTEXT = _cached_ml_team_context(signature)
        _RUNTIME_TEAM_CONTEXT_SIGNATURE = signature
    return _RUNTIME_TEAM_CONTEXT


def _ml_fallback_team_row(team: str, ctx: pd.DataFrame) -> pd.Series:
    """League-average team row so Moneyline can show every scheduled game."""
    team = _team_key_for_matchup(team)
    if ctx is not None and not ctx.empty and "Team" in ctx.columns:
        hit = ctx[ctx["Team"].astype(str) == team]
        if not hit.empty:
            return hit.iloc[0]
        pace = pd.to_numeric(ctx.get("Pace", pd.Series(dtype=float)), errors="coerce").median()
        ortg = pd.to_numeric(ctx.get("ORtg", pd.Series(dtype=float)), errors="coerce").median()
        drtg = pd.to_numeric(ctx.get("DRtg", pd.Series(dtype=float)), errors="coerce").median()
    else:
        pace = ortg = drtg = np.nan
    pace = 78.0 if pd.isna(pace) else pace
    ortg = 101.0 if pd.isna(ortg) else ortg
    drtg = 101.0 if pd.isna(drtg) else drtg
    return pd.Series({
        "Team": team,
        "Pace": safe_float(pace, 78.0),
        "ORtg": safe_float(ortg, 101.0),
        "DRtg": safe_float(drtg, 101.0),
        "NetRtg": 0.0,
        "Moneyline Context": "league-average fallback",
    })


def _ml_sane_rating(value: Any, fallback: float, low: float = 88.0, high: float = 120.0) -> float:
    """Reject corrupt team-rating values before they can crater a game projection."""
    v = safe_float(value, np.nan)
    if pd.isna(v) or v < low or v > high:
        return float(fallback)
    return float(v)


def _project_game_score(team_row: pd.Series, opp_row: pd.Series) -> Tuple[float, float]:
    """App119 absolute-score model with rating sanity and PPG anchoring.

    The previous formula could produce a 60s team score when a malformed DRtg
    leaked into context.  This version uses a league-centered offense/defense
    interaction and shrinks extreme outputs toward actual scoring/points-allowed
    baselines when those fields exist.
    """
    tp = safe_float(team_row.get("Pace"), np.nan)
    op = safe_float(opp_row.get("Pace"), np.nan)
    if pd.notna(tp) and not (70.0 <= tp <= 92.0):
        tp = np.nan
    if pd.notna(op) and not (70.0 <= op <= 92.0):
        op = np.nan
    if pd.notna(tp) and pd.notna(op):
        pace = float(math.sqrt(max(tp, 1.0) * max(op, 1.0)))
    else:
        pace = float(np.nanmean([tp, op])) if pd.notna(tp) or pd.notna(op) else 80.0
    pace = float(np.clip(pace, 72.0, 89.0))

    # Dynamic reference when possible; 104 is a conservative WNBA fallback.
    league_ref = 104.0
    ortg = _ml_sane_rating(team_row.get("ORtg"), league_ref)
    opp_drtg = _ml_sane_rating(opp_row.get("DRtg"), league_ref)
    expected_eff = league_ref + 0.58 * (ortg - league_ref) + 0.42 * (opp_drtg - league_ref)
    core_score = pace * expected_eff / 100.0

    ppg = safe_float(team_row.get("PTS_per_game", team_row.get("PPG")), np.nan)
    opp_allowed = safe_float(opp_row.get("PointsAllowed_per_game", opp_row.get("PointsAllowed")), np.nan)
    anchors = [v for v in [ppg, opp_allowed] if pd.notna(v) and 60.0 <= v <= 105.0]
    if anchors:
        anchor = float(np.mean(anchors))
        score = 0.72 * core_score + 0.28 * anchor
        # Prevent a malformed rating from moving more than 10 points away from
        # the observable scoring environment.
        score = float(np.clip(score, anchor - 10.0, anchor + 10.0))
    else:
        score = core_score
    return float(np.clip(score, 64.0, 103.0)), pace


def _simulate_wnba_game(
    team_row: pd.Series,
    opp_row: pd.Series,
    sims: int = 15000,
    seed_key: str = "",
    total_line: Optional[float] = None,
    team_mean_override: Optional[float] = None,
    opp_mean_override: Optional[float] = None,
) -> Dict[str, Any]:
    """Correlated game simulation centered on the sanity-checked score model.

    App120 can optionally supply injury/rotation-adjusted team means from the
    Elite game environment.  Existing callers remain backward compatible.
    """
    base_team_mean, pace = _project_game_score(team_row, opp_row)
    base_opp_mean, _ = _project_game_score(opp_row, team_row)
    team_mean = safe_float(team_mean_override, base_team_mean)
    opp_mean = safe_float(opp_mean_override, base_opp_mean)
    if pd.isna(team_mean): team_mean = base_team_mean
    if pd.isna(opp_mean): opp_mean = base_opp_mean
    team_mean = float(np.clip(team_mean, 60.0, 105.0))
    opp_mean = float(np.clip(opp_mean, 60.0, 105.0))
    seed = stable_seed("wnba_game_sim_app119", seed_key, team_row.get("Team"), opp_row.get("Team"), PROJECTION_ENGINE_VERSION)
    rng = np.random.default_rng(seed)
    n = int(max(1000, sims))
    # Shared pace shock creates realistic score correlation; independent
    # efficiency shocks decide the margin.
    sim_pace = np.clip(rng.normal(pace, 2.15, n), 70.0, 92.0)
    pace_factor = sim_pace / max(pace, 1e-6)
    shared_env = rng.normal(0.0, 2.2, n)
    team_scores = np.clip(team_mean * pace_factor + shared_env + rng.normal(0.0, 6.4, n), 45.0, 118.0)
    opp_scores = np.clip(opp_mean * pace_factor + shared_env + rng.normal(0.0, 6.4, n), 45.0, 118.0)
    margins = team_scores - opp_scores
    totals = team_scores + opp_scores
    win_pct = float((margins > 0).mean() * 100.0)
    spread_mean = float(np.mean(margins))
    favorite = str(team_row.get("Team")) if spread_mean >= 0 else str(opp_row.get("Team"))
    tl = safe_float(total_line, np.nan)
    if pd.notna(tl) and tl > 0:
        total_over_pct = float((totals > tl).mean() * 100.0)
        total_under_pct = float((totals < tl).mean() * 100.0)
    else:
        total_over_pct = np.nan
        total_under_pct = np.nan
    return {
        "Team Sim Score": round(float(np.mean(team_scores)), 1),
        "Opponent Sim Score": round(float(np.mean(opp_scores)), 1),
        "Sim Win %": round(win_pct, 1),
        "Sim Total": round(float(np.mean(totals)), 1),
        "Sim Total Over %": round(total_over_pct, 1) if pd.notna(total_over_pct) else np.nan,
        "Sim Total Under %": round(total_under_pct, 1) if pd.notna(total_under_pct) else np.nan,
        "Sim Spread": round(spread_mean, 1),
        "Sim Favorite": favorite,
        "Sim Pace": round(float(np.mean(sim_pace)), 1),
        "Sim Count": n,
        "Market Total Line": tl if pd.notna(tl) else np.nan,
        "Total Line Status": "SUPPLIED" if pd.notna(tl) and tl > 0 else "NO_REAL_TOTAL_LINE",
    }


@st.cache_data(ttl=180, show_spinner=False)
def fetch_underdog_wnba_schedule_feed() -> Tuple[pd.DataFrame, pd.DataFrame]:
    """Read the complete live WNBA game slate directly from Underdog.

    Player props are not guaranteed for every game, so Moneyline must consume
    the feed's `games` collection instead of trying to infer the slate only
    from accepted player-line rows.
    """
    headers = {
        "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 Mobile/15E148 Underdog/1.0",
        "Accept": "application/json, text/plain, */*",
        "Origin": "https://underdogfantasy.com",
        "Referer": "https://underdogfantasy.com/",
    }
    debug = []
    for url in UNDERDOG_URLS:
        try:
            response = requests.get(url, headers=headers, timeout=25)
            if response.status_code != 200:
                debug.append({"Source": "Underdog games", "URL": url, "Status": f"HTTP {response.status_code}", "Rows": 0})
                continue
            payload = response.json()
        except Exception as exc:
            debug.append({"Source": "Underdog games", "URL": url, "Status": f"error: {str(exc)[:160]}", "Rows": 0})
            continue

        rows = []
        games = payload.get("games", []) if isinstance(payload, dict) else []
        for game in games:
            if not isinstance(game, dict):
                continue
            sport = str(game.get("sport_id") or game.get("sport_name") or "").upper()
            if "WNBA" not in sport:
                continue
            status = str(game.get("status") or "").lower()
            if status in {"cancelled", "canceled", "postponed"}:
                continue
            event = str(
                game.get("abbreviated_title")
                or game.get("title")
                or game.get("full_team_names_title")
                or game.get("short_title")
                or ""
            ).strip()
            away, home = _parse_event_teams_from_text(event)
            if not away or not home or away == home:
                continue
            start_raw = str(game.get("scheduled_at") or ((game.get("scoreboard") or {}).get("scheduled_at")) or "")
            start_local = pd.NaT
            slate_date = ""
            if start_raw:
                try:
                    start_utc = pd.to_datetime(start_raw, errors="coerce", utc=True)
                    if pd.notna(start_utc):
                        start_local = start_utc.tz_convert(app_timezone())
                        slate_date = str(start_local.date())
                except Exception:
                    start_local = pd.NaT
            rows.append({
                "GameID": str(game.get("id") or ""),
                "GameDate": start_local,
                "SlateDate": slate_date,
                "Away": away,
                "Home": home,
                "Matchup": f"{away} @ {home}",
                "Source": "Underdog live games",
                "Status": status or "scheduled",
                "Event": event,
            })
        feed = pd.DataFrame(rows)
        if not feed.empty:
            feed = feed.drop_duplicates(subset=["GameID", "Away", "Home"], keep="last")
            debug.append({"Source": "Underdog games", "URL": url, "Status": "ok", "Rows": len(feed)})
            return feed.reset_index(drop=True), pd.DataFrame(debug)
        debug.append({"Source": "Underdog games", "URL": url, "Status": "no WNBA games", "Rows": 0})
    return pd.DataFrame(columns=["GameID", "GameDate", "SlateDate", "Away", "Home", "Matchup", "Source", "Status", "Event"]), pd.DataFrame(debug)


def _moneyline_pairs_from_schedule(mode: str = "Today") -> List[Dict[str, Any]]:
    schedule_frames = []
    target = slate_target_date(mode)

    # Primary source: the Underdog game slate saved by the explicit Refresh
    # button. Merely opening/changing tabs never performs another network pull.
    try:
        ud_sched = st.session_state.get("wnba_moneyline_games", pd.DataFrame())
        if (ud_sched is None or ud_sched.empty) and UNDERDOG_GAMES_CACHE_FILE.exists():
            ud_sched = pd.read_csv(UNDERDOG_GAMES_CACHE_FILE, low_memory=False)
        if ud_sched is not None and not ud_sched.empty:
            if target is not None and "SlateDate" in ud_sched.columns:
                ud_sched = ud_sched[ud_sched["SlateDate"].astype(str).eq(str(target))].copy()
            if not ud_sched.empty:
                schedule_frames.append(ud_sched)
    except Exception as exc:
        st.session_state["wnba_moneyline_underdog_error"] = str(exc)[:220]

    # Secondary source: the schedule cache already updated by the same Refresh.
    if not schedule_frames:
        cached = schedule_for_slate(mode)
        if cached is not None and not cached.empty:
            schedule_frames.append(cached.copy())

    sched = pd.concat(schedule_frames, ignore_index=True, sort=False) if schedule_frames else pd.DataFrame()
    if sched is None or sched.empty:
        return []
    pairs = []
    seen = set()
    for _, r in sched.iterrows():
        away = _team_key_for_matchup(r.get("Away"))
        home = _team_key_for_matchup(r.get("Home"))
        if not away or not home or away == home:
            continue
        pair_key = tuple(sorted([away, home]))
        if pair_key in seen:
            continue
        seen.add(pair_key)
        pairs.append({
            "key": pair_key,
            "team": away,
            "opp": home,
            "matchup": f"{away} @ {home}",
            "source": str(r.get("Source", "schedule") or "schedule"),
            "game_date": str(r.get("GameDate", ""))[:19],
            "game_id": str(r.get("GameID", "") or ""),
        })
    return pairs


def _moneyline_pairs_from_lines(lines_df: pd.DataFrame) -> List[Dict[str, Any]]:
    if lines_df is None or lines_df.empty:
        return []
    d = _ensure_line_matchups_for_filter(lines_df)
    pairs = []
    seen = set()
    if "Matchup" in d.columns:
        for matchup in d["Matchup"].dropna().astype(str).unique().tolist():
            a, b = _parse_event_teams_from_text(matchup)
            if not a or not b:
                continue
            key = tuple(sorted([a, b]))
            if key in seen:
                continue
            seen.add(key)
            pairs.append({"key": key, "team": a, "opp": b, "matchup": f"{a} @ {b}", "source": "pulled lines", "game_date": ""})
    if {"Team", "Opponent"}.issubset(d.columns):
        for _, r in d[["Team", "Opponent"]].drop_duplicates().iterrows():
            a = _team_key_for_matchup(r.get("Team"))
            b = _team_key_for_matchup(r.get("Opponent"))
            if not a or not b or a == b:
                continue
            key = tuple(sorted([a, b]))
            if key in seen:
                continue
            seen.add(key)
            pairs.append({"key": key, "team": a, "opp": b, "matchup": f"{a} @ {b}", "source": "pulled lines", "game_date": ""})
    for raw_col in ["Raw", "Event", "Game", "GameInfo", "Description"]:
        if raw_col not in d.columns or "_parse_event_teams_from_text" not in globals():
            continue
        for raw in d[raw_col].dropna().astype(str).unique().tolist():
            a, b = _parse_event_teams_from_text(raw)
            if not a or not b or a == b:
                continue
            key = tuple(sorted([a, b]))
            if key in seen:
                continue
            seen.add(key)
            pairs.append({"key": key, "team": a, "opp": b, "matchup": f"{a} @ {b}", "source": f"pulled {raw_col}", "game_date": ""})
    return pairs


def _moneyline_pairs_from_board(board_df: pd.DataFrame) -> List[Dict[str, Any]]:
    if board_df is None or board_df.empty or not {"Team", "Opponent"}.issubset(board_df.columns):
        return []
    pairs = []
    cols = ["Team", "Opponent", "Matchup"] if "Matchup" in board_df.columns else ["Team", "Opponent"]
    seen = set()
    for _, r in board_df[cols].drop_duplicates().iterrows():
        a = _team_key_for_matchup(r.get("Team"))
        b = _team_key_for_matchup(r.get("Opponent"))
        if not a or not b or a == b:
            continue
        key = tuple(sorted([a, b]))
        if key in seen:
            continue
        seen.add(key)
        pairs.append({"key": key, "team": a, "opp": b, "matchup": str(r.get("Matchup", f"{a} @ {b}")), "source": "prop board", "game_date": ""})
    return pairs


def _wnba_game_script_context(row: pd.Series) -> Dict[str, Any]:
    """Small WNBA-specific game model used by both ML cards and prop scoring."""
    ctx = _ml_team_context()
    if ctx is None or ctx.empty:
        return {
            "ok": False,
            "factor": 1.0,
            "support": 0,
            "note": "WNBA ML game script unavailable",
        }
    ctx_map = {str(r.get("Team")): r for _, r in ctx.iterrows()}
    team = _team_key_for_matchup(row.get("Team"))
    opp = _team_key_for_matchup(row.get("Opponent"))
    if not team or not opp or team not in ctx_map or opp not in ctx_map:
        return {
            "ok": False,
            "factor": 1.0,
            "support": 0,
            "note": "WNBA ML game script missing team/opponent context",
        }

    team_score, pace = _project_game_score(ctx_map[team], ctx_map[opp])
    opp_score, _ = _project_game_score(ctx_map[opp], ctx_map[team])
    total = team_score + opp_score
    spread = team_score - opp_score
    win_prob = float(np.clip(50.0 + spread * 4.0, 18.0, 82.0))
    blowout_risk = float(np.clip((abs(spread) - 8.0) * 4.5, 0.0, 36.0))
    pace_move = float(np.clip((pace - 79.0) / 80.0, -0.025, 0.030))
    team_total_move = float(np.clip((team_score - 79.5) / 240.0, -0.030, 0.035))
    blowout_move = -float(np.clip(blowout_risk / 1400.0, 0.0, 0.025))
    market = str(row.get("Market", "")).upper()

    if market == "PTS":
        factor = 1.0 + 0.45 * pace_move + 0.55 * team_total_move + blowout_move
    elif market == "AST":
        factor = 1.0 + 0.40 * pace_move + 0.50 * team_total_move + 0.50 * blowout_move
    elif market == "REB":
        # Rebounds need pace/missed shots more than raw team total.
        opp_drtg = safe_float(ctx_map[opp].get("DRtg"), 101.0)
        miss_move = float(np.clip((opp_drtg - 101.0) / 320.0, -0.018, 0.020))
        factor = 1.0 + 0.55 * pace_move + miss_move + 0.70 * blowout_move
    elif market == "PRA":
        factor = 1.0 + 0.43 * pace_move + 0.45 * team_total_move + 0.75 * blowout_move
    else:
        factor = 1.0 + 0.35 * pace_move + 0.35 * team_total_move + 0.60 * blowout_move
    factor = float(np.clip(factor, 0.965, 1.040))

    lean = str(row.get("Lean", "")).upper()
    support = 0
    high_env = total >= 162.0 or pace >= 80.5 or team_score >= 81.0
    low_env = total <= 156.0 or pace <= 77.5 or team_score <= 76.5
    if lean == "OVER" and high_env and blowout_risk < 24:
        support += 1
    if lean == "UNDER" and low_env:
        support += 1
    if blowout_risk >= 24 and market in {"PTS", "AST", "PRA"}:
        support -= 1 if lean == "OVER" else 0
    if lean == "UNDER" and blowout_risk >= 24:
        support += 1

    fav = team if spread >= 0 else opp
    note = (
        f"{team} {team_score:.1f} vs {opp} {opp_score:.1f}; "
        f"total {total:.1f}; {fav} by {abs(spread):.1f}; "
        f"{win_prob:.0f}% team win; pace {pace:.1f}; blowout {blowout_risk:.0f}%"
    )
    return {
        "ok": True,
        "factor": factor,
        "support": int(np.clip(support, -1, 2)),
        "note": note,
        "team_score": team_score,
        "opp_score": opp_score,
        "total": total,
        "spread": spread,
        "win_prob": win_prob,
        "pace": pace,
        "blowout_risk": blowout_risk,
    }


def render_wnba_ml_system(board_df: pd.DataFrame, key_prefix: str = "ml_system", mode: str = "Today") -> pd.DataFrame:
    st.markdown("#### WNBA Moneyline / Game Script")
    st.caption("Game-level model using pace, ORtg, DRtg, projected score, 15k simulation, spread, total and blowout risk.")
    ctx = _ml_team_context()
    if ctx.empty:
        st.warning("Team context is unavailable. Scheduled games are shown with league-average fallback ratings until team data refreshes.")

    schedule_pairs = _moneyline_pairs_from_schedule(mode)
    ml_lines = st.session_state.get("wnba_lines_all", pd.DataFrame())
    if ml_lines is not None and not ml_lines.empty and mode != "All Lines":
        try:
            ml_lines, _ = filter_lines_for_slate(ml_lines, mode)
        except Exception:
            pass
    line_pairs = _moneyline_pairs_from_lines(ml_lines)
    ml_board = board_df.copy() if board_df is not None else pd.DataFrame()
    if ml_board is not None and not ml_board.empty and mode != "All Lines":
        ml_board = filter_projection_board_for_slate(ml_board, mode)
    board_pairs = _moneyline_pairs_from_board(ml_board)
    pairs = []
    seen = set()
    for p in schedule_pairs + line_pairs + board_pairs:
        key = p.get("key")
        if not key or key in seen:
            continue
        seen.add(key)
        pairs.append(p)
    if not pairs:
        st.error(
            f"No {mode.lower()} WNBA matchups were returned by Underdog, ESPN, the saved schedule, "
            "or the current prop board. Open Moneyline coverage debug below for the source response."
        )
        with st.expander("Moneyline coverage debug", expanded=True):
            st.write({
                "slate": mode,
                "line_rows": 0 if ml_lines is None else len(ml_lines),
                "board_rows": 0 if ml_board is None else len(ml_board),
                "underdog_error": st.session_state.get("wnba_moneyline_underdog_error", ""),
                "espn_error": st.session_state.get("wnba_moneyline_schedule_error", ""),
            })
            ud_dbg = st.session_state.get("wnba_moneyline_underdog_debug", pd.DataFrame())
            if ud_dbg is not None and not getattr(ud_dbg, "empty", True):
                st.dataframe(ud_dbg, use_container_width=True, hide_index=True)
        return pd.DataFrame()
    if schedule_pairs:
        st.caption(f"Moneyline games: {len(pairs)} total ({len(schedule_pairs)} live/scheduled, {len(line_pairs)} from pulled lines, {len(board_pairs)} from prop board).")
    else:
        st.warning("Moneyline is using pulled-line/prop-board matchups because today's live schedule could not be loaded.")
    with st.expander("Moneyline coverage debug", expanded=False):
        st.write({
            "schedule_pairs": [p.get("matchup") for p in schedule_pairs],
            "line_pairs": [p.get("matchup") for p in line_pairs],
            "board_pairs": [p.get("matchup") for p in board_pairs],
            "rendered_pairs": [p.get("matchup") for p in pairs],
            "moneyline_feed_version": MONEYLINE_FEED_VERSION,
            "schedule_error": st.session_state.get("wnba_moneyline_schedule_error", ""),
            "underdog_error": st.session_state.get("wnba_moneyline_underdog_error", ""),
        })
        ud_dbg = st.session_state.get("wnba_moneyline_underdog_debug", pd.DataFrame())
        if ud_dbg is not None and not getattr(ud_dbg, "empty", True):
            st.dataframe(ud_dbg, use_container_width=True, hide_index=True)
        dbg = st.session_state.get("wnba_moneyline_schedule_debug", pd.DataFrame())
        if dbg is not None and not getattr(dbg, "empty", True):
            st.dataframe(dbg, use_container_width=True, hide_index=True)

    # App120: use the same injury/rotation-aware game environment that feeds
    # the Elite player budgets whenever those caches are available.  If any
    # piece is missing, Moneyline safely falls back to the standalone team model.
    try:
        _ml_elite_base = _elite_latest_base(load_dataset("master_features"))
        _ml_team_season = _pts_v2_latest_team_table("team_season_stats")
        _ml_team_opp = _pts_v2_latest_team_table("team_opponent_stats")
        _ml_team_recent = _pts_v2_latest_team_table("team_recent_stats")
        _ml_inactive, _ml_questionable, _ml_injury_note = _elite_inactive_by_team(mode)
    except Exception as _ml_elite_exc:
        _ml_elite_base = pd.DataFrame(); _ml_team_season = pd.DataFrame(); _ml_team_opp = pd.DataFrame(); _ml_team_recent = pd.DataFrame()
        _ml_inactive, _ml_questionable = {}, {}
        _ml_injury_note = f"elite ML context unavailable: {str(_ml_elite_exc)[:120]}"
    try:
        _ml_injury_summary = _app121_injury_summary_by_team(mode)
    except Exception:
        _ml_injury_summary = {}

    cards = []
    game_rows = []
    for p in pairs[:12]:
        a, b = p["team"], p["opp"]
        ar, br = _ml_fallback_team_row(a, ctx), _ml_fallback_team_row(b, ctx)
        a_score, pace = _project_game_score(ar, br)
        b_score, _ = _project_game_score(br, ar)
        _elite_ml_env = None
        try:
            if not _ml_elite_base.empty and not _ml_team_season.empty and not _ml_team_opp.empty:
                _ml_game_row = pd.Series({"Team":a,"Opponent":b,"HomeAway":"AWAY"})
                _elite_ml_env = _elite_game_environment(
                    a,b,_ml_game_row,_ml_elite_base,_ml_team_season,_ml_team_opp,_ml_team_recent,
                    _ml_inactive,_ml_questionable,
                )
                if _elite_ml_env.get("data_ok"):
                    a_score = safe_float(_elite_ml_env.get("team_score"), a_score)
                    b_score = safe_float(_elite_ml_env.get("opp_score"), b_score)
                    pace = safe_float(_elite_ml_env.get("pace"), pace)
        except Exception:
            _elite_ml_env = None
        sim = _simulate_wnba_game(
            ar, br, sims=WNBA_MONTE_CARLO_SIMS, seed_key=f"{a}-{b}", total_line=None,
            team_mean_override=a_score, opp_mean_override=b_score,
        )
        a_score = safe_float(sim.get("Team Sim Score"), a_score)
        b_score = safe_float(sim.get("Opponent Sim Score"), b_score)
        spread = a_score - b_score
        total = a_score + b_score
        ml_team = sim.get("Sim Favorite") or (a if spread >= 0 else b)
        raw_a_win = safe_float(sim.get("Sim Win %"), 50.0)
        # Freshness is confidence, not score direction. Stale active-season
        # team data shrinks the displayed win probability toward 50 instead of
        # pretending the stale model is still highly certain.
        _ml_latest = pd.to_datetime((_elite_ml_env or {}).get("latest_data"), errors="coerce")
        _ml_target = pd.to_datetime(str(p.get("game_date", "")), errors="coerce")
        if pd.isna(_ml_target):
            try: _ml_target = pd.to_datetime(slate_target_date(mode), errors="coerce")
            except Exception: _ml_target = pd.to_datetime(datetime.now(tz=app_timezone()).date(), errors="coerce")
        _ml_age = _app121_context_lag_days(a,b,_ml_latest,_ml_target)
        if _elite_ml_env is None or not (_elite_ml_env or {}).get("data_ok"):
            _ml_fresh_factor, _ml_fresh_status = 0.35, "FALLBACK"
        elif pd.notna(_ml_age) and _ml_age > 7:
            _ml_fresh_factor, _ml_fresh_status = 0.35, "CRITICAL STALE"
        elif pd.notna(_ml_age) and _ml_age > 2:
            _ml_fresh_factor, _ml_fresh_status = 0.72, "STALE"
        else:
            _ml_fresh_factor, _ml_fresh_status = 1.0, "FRESH"
        a_win = float(np.clip(50.0 + (raw_a_win-50.0)*_ml_fresh_factor, 15.0, 85.0))
        b_win = 100.0 - a_win
        ml_prob = a_win if ml_team == a else b_win
        dog_team = b if ml_team == a else a
        dog_prob = b_win if ml_team == a else a_win
        _total_over = safe_float(sim.get("Sim Total Over %"), np.nan)
        _total_under = safe_float(sim.get("Sim Total Under %"), np.nan)
        total_side = "MODEL TOTAL" if pd.isna(_total_over) or pd.isna(_total_under) else ("OVER" if _total_over >= _total_under else "UNDER")
        total_conf = np.nan if pd.isna(_total_over) or pd.isna(_total_under) else max(_total_over, _total_under)
        sim_spread = safe_float(sim.get("Sim Spread"), spread)
        spread_conf = min(82, 50 + abs(sim_spread) * 4.5)
        blowout = float(np.clip((abs(sim_spread) - 8.0) * 4.5, 0.0, 36.0))
        total_line = safe_float(sim.get("Market Total Line"), np.nan)
        total_edge = safe_float(sim.get("Sim Total"), total) - total_line if pd.notna(total_line) else np.nan
        total_bar = float(np.clip(total_conf, 0, 100)) if pd.notna(total_conf) else 0.0
        a_logo = _team_logo_html(a, "wnba-ml-logo")
        b_logo = _team_logo_html(b, "wnba-ml-logo")
        a_nick = html.escape(TEAM_NICKNAMES.get(a, a))
        b_nick = html.escape(TEAM_NICKNAMES.get(b, b))
        source_note = html.escape(str(p.get("source", "schedule")))
        game_date_note = html.escape(str(p.get("game_date", "")))
        ml_fresh_note = html.escape(f"{_ml_fresh_status}{(' · '+str(int(_ml_age))+'d') if pd.notna(_ml_age) else ''}")
        _inj_bits=[]
        if _ml_injury_summary.get(a): _inj_bits.append(f"{a}: {_ml_injury_summary.get(a)}")
        if _ml_injury_summary.get(b): _inj_bits.append(f"{b}: {_ml_injury_summary.get(b)}")
        if not _inj_bits:
            _fallback_inj=str((_elite_ml_env or {}).get("injury_names", "") or "").strip()
            if _fallback_inj and _fallback_inj.lower() != "none": _inj_bits.append(f"{a}: {_fallback_inj}")
        ml_injury_names = html.escape(" | ".join(_inj_bits))
        fav_label = html.escape(str(ml_team))
        ml_note = f"{fav_label} FAV" if ml_prob >= 50 else "NO CLEAR FAV"
        game_rows.append({
            "Slate": mode,
            "Game Time": str(p.get("game_date", "")),
            "Matchup": f"{a} @ {b}",
            "Away": a,
            "Home": b,
            "Projected Away Score": round(a_score, 1),
            "Projected Home Score": round(b_score, 1),
            "Projected Total": round(safe_float(sim.get("Sim Total"), total), 1),
            "Projected Favorite": ml_team,
            "Projected Spread": round(abs(sim_spread), 1),
            "Favorite Win Probability": round(ml_prob, 1),
            "Underdog Win Probability": round(dog_prob, 1),
            "Projected Total Side": total_side,
            "Total Model Confidence": round(total_conf, 1),
            "Game Pace": round(safe_float(sim.get("Sim Pace"), pace), 1),
            "Blowout Risk": round(blowout, 1),
            "Simulation Count": int(safe_float(sim.get("Sim Count"), WNBA_MONTE_CARLO_SIMS)),
            "Moneyline Feed Version": MONEYLINE_FEED_VERSION,
            "Matchup Source": str(p.get("source", "schedule")),
            "Away Context": str(ar.get("Moneyline Context", "team data")),
            "Home Context": str(br.get("Moneyline Context", "team data")),
            "Raw Sim Favorite Win Probability": round(max(raw_a_win, 100.0-raw_a_win), 1),
            "ML Data Freshness": _ml_fresh_status,
            "ML Data Age Days": _ml_age,
            "ML Injury Adjusted": bool(_ml_injury_summary.get(a) or _ml_injury_summary.get(b)),
            "ML Injury Names Away": str(_ml_injury_summary.get(a, "")),
            "ML Injury Names Home": str(_ml_injury_summary.get(b, "")),
            "ML Injury Summary": " | ".join(_inj_bits),
            "ML Injury Feed Note": str(_ml_injury_note),
        })
        cards.append(
            "<div class='wnba-ml-card'>"
            f"<div class='wnba-ml-source'>{source_note}{' · ' + game_date_note if game_date_note else ''} · {ml_fresh_note}{(' · INJ '+ml_injury_names) if ml_injury_names else ''}</div>"
            "<div class='wnba-ml-teams'>"
            f"<div class='wnba-ml-team'>{a_logo}<b>{html.escape(a)}</b><span>{a_nick}</span><strong>{a_score:.1f}</strong><em>{a_win:.0f}% win</em></div>"
            f"<div class='wnba-ml-mid'><span>{safe_float(sim.get('Sim Pace'), pace):.1f} POSS</span><div class='wnba-ml-poss'><i style='width:{ml_prob:.0f}%'></i></div><small>{ml_prob:.0f}%/{dog_prob:.0f}%</small><b>{ml_note}</b></div>"
            f"<div class='wnba-ml-team'>{b_logo}<b>{html.escape(b)}</b><span>{b_nick}</span><strong>{b_score:.1f}</strong><em>{b_win:.0f}% win</em></div>"
            "</div>"
            "<div class='wnba-ml-total'>"
            f"<div><small>Game Total</small><strong>{safe_float(sim.get('Sim Total'), total):.1f}</strong><span>{('market line '+format(total_line,'.1f')) if pd.notna(total_line) else 'projection only · no real total line'}</span></div>"
            f"<b class='wnba-ml-total-side'>{total_side}</b><em>{(format(total_conf,'.0f')+'%') if pd.notna(total_conf) else 'NO BET CONF'}</em>"
            f"<div class='wnba-ml-total-bar'><i style='width:{total_bar:.0f}%'></i></div><p>{('OVER '+format(_total_over,'.0f')+'%') if pd.notna(_total_over) else 'Total probabilities disabled'} <span>{('UNDER '+format(_total_under,'.0f')+'%') if pd.notna(_total_under) else ''}</span></p>"
            "</div>"
            "<div class='wnba-ml-bottom'>"
            f"<div><small>Spread</small><b>{fav_label}</b><span>{fav_label} -{abs(sim_spread):.1f}</span><em>{spread_conf:.0f}% conf</em></div>"
            f"<div><small>Moneyline</small><b>{fav_label}</b><span>{ml_prob:.0f}% WIN</span><em>{dog_team} {dog_prob:.0f}%</em></div>"
            f"<div><small>Pace</small><b>{safe_float(sim.get('Sim Pace'), pace):.1f}</b><span>model pace</span></div>"
            f"<div><small>ORtg</small><b>{safe_float(ar.get('ORtg'), np.nan):.1f}</b><span>{a} offense</span></div>"
            f"<div><small>Blowout</small><b>{blowout:.0f}%</b><span>risk</span></div>"
            "</div>"
            f"<div class='wnba-ml-sim'>15k sim: {html.escape(a)} {sim.get('Team Sim Score')} · {html.escape(b)} {sim.get('Opponent Sim Score')} · total {sim.get('Sim Total')} · winner {fav_label} · confidence data {ml_fresh_note}</div>"
            "</div>"
        )
    if not cards:
        st.info("No ML cards could be built from current team context.")
        return pd.DataFrame()
    ml_html = "<style>"
    ml_html += ".wnba-ml-wrap{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:16px;margin:10px 0 18px;background:#070912;padding:4px}"
    ml_html += ".wnba-ml-card{background:linear-gradient(180deg,#0b0f18 0%,#0f1722 100%);border:1px solid rgba(250,204,21,.56);border-radius:16px;padding:18px;color:#e5e7eb;box-shadow:0 18px 42px rgba(0,0,0,.35);overflow:hidden;position:relative}"
    ml_html += ".wnba-ml-source{position:absolute;top:8px;left:12px;color:#94a3b8;font-size:.68rem;text-transform:uppercase;letter-spacing:.04em}"
    ml_html += ".wnba-ml-card:before{content:'';position:absolute;inset:0;border-radius:16px;background:radial-gradient(circle at 18% 8%,rgba(250,204,21,.12),transparent 28%),radial-gradient(circle at 82% 8%,rgba(96,165,250,.10),transparent 32%);pointer-events:none}.wnba-ml-card>*{position:relative;z-index:1}"
    ml_html += ".wnba-ml-teams{display:grid;grid-template-columns:minmax(0,1fr) 118px minmax(0,1fr);gap:14px;align-items:start}.wnba-ml-team{text-align:center;min-width:0}.wnba-ml-team .owp-team-logo{display:flex;align-items:center;justify-content:center;margin:0 auto 8px;width:58px;height:58px;border-radius:16px;background:#101722;border:1px solid rgba(250,204,21,.32);overflow:hidden;box-shadow:inset 0 0 18px rgba(255,255,255,.04)}.wnba-ml-team .owp-team-logo-img{width:100%;height:100%;object-fit:contain;display:block;padding:7px;box-sizing:border-box}.wnba-ml-team .owp-team-logo-text{font-size:.78rem;font-weight:1000;color:#fbbf24}.wnba-ml-team b{display:block;font-size:1.75rem;color:#f8fafc;line-height:1}.wnba-ml-team span{display:block;color:#7c8798;font-size:.82rem;margin-top:3px}.wnba-ml-team strong{display:block;color:#fbbf24;font-size:2.55rem;font-weight:400;line-height:1.1;margin-top:8px}.wnba-ml-team em{display:block;color:#94a3b8;font-style:normal;font-size:.82rem}"
    ml_html += ".wnba-ml-mid{text-align:center;padding-top:40px}.wnba-ml-mid span{display:block;color:#64748b;font-size:.76rem;font-weight:900}.wnba-ml-mid small{display:block;color:#94a3b8;margin-top:3px}.wnba-ml-mid b{display:block;color:#fbbf24;font-size:.78rem;margin-top:4px}.wnba-ml-poss{height:7px;background:#1f2937;border-radius:999px;overflow:hidden;margin:6px 0}.wnba-ml-poss i{display:block;height:100%;background:#fbbf24;border-radius:999px}"
    ml_html += ".wnba-ml-total{margin-top:18px;background:rgba(16,23,34,.96);border:1px solid rgba(148,163,184,.10);border-radius:12px;padding:14px;position:relative}.wnba-ml-total small{display:block;color:#7c8798;text-transform:uppercase;font-size:.68rem}.wnba-ml-total strong{font-size:2.7rem;color:#fb3f7c;font-weight:400}.wnba-ml-total span{margin-left:10px;color:#4ade80;font-weight:900}.wnba-ml-total span.under{color:#60a5fa}.wnba-ml-total-side{position:absolute;right:18px;top:22px;color:#fbbf24;font-size:1.25rem}.wnba-ml-total em{position:absolute;right:18px;top:52px;color:#fef3c7;border:1px solid rgba(250,204,21,.55);border-radius:999px;padding:2px 8px;font-style:normal;font-size:.72rem}.wnba-ml-total-bar{height:8px;background:#1f2937;border-radius:999px;overflow:hidden;margin-top:10px}.wnba-ml-total-bar i{display:block;height:100%;background:linear-gradient(90deg,#f59e0b,#facc15)}.wnba-ml-total p{display:flex;justify-content:space-between;color:#fbbf24;font-size:.72rem;margin:6px 0 0}.wnba-ml-total p span{margin:0;color:#94a3b8}"
    ml_html += ".wnba-ml-bottom{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-top:10px}.wnba-ml-bottom div{background:rgba(16,23,34,.96);border:1px solid rgba(148,163,184,.08);border-radius:9px;padding:9px;text-align:center;min-width:0}.wnba-ml-bottom small{display:block;color:#7c8798;text-transform:uppercase;font-size:.62rem}.wnba-ml-bottom b{display:block;color:#fbbf24}.wnba-ml-bottom span,.wnba-ml-bottom em{display:block;color:#94a3b8;font-size:.72rem;font-style:normal}.wnba-ml-sim{margin-top:10px;color:#c4b5fd;font-size:.78rem;line-height:1.35;white-space:normal}"
