# ============================================================================
# v3.4.4 — CALIBRATED TRUE-SIDE ENGINE
# Goals:
#   • no duplicate pace/matchup/role boosts
#   • robust player baseline with conservative recent-form weighting
#   • market-aware Bayesian shrinkage (small, confidence-dependent)
#   • PRA equals corrected PTS + REB + AST exactly
#   • calibrated probabilities with uncertainty inflation
#   • NEUTRAL/NO-PLAY zone for edges too small to be meaningful
#   • slate bias is diagnosed, never artificially forced to 50/50
# ============================================================================
_make_projection_board_v344_input = _historical_make_projection_board_6


def _v344_numeric(values):
    out = []
    for x in values:
        try:
            x = float(x)
            if np.isfinite(x):
                out.append(x)
        except Exception:
            pass
    return out


def _v344_player_lookup(base: pd.DataFrame) -> pd.DataFrame:
    if base is None or base.empty:
        return pd.DataFrame()
    b = base.copy()
    if "NameKey" not in b.columns:
        b["NameKey"] = b.get("Player", "").map(normalize_name)
    return b.drop_duplicates("NameKey").set_index("NameKey")


def _v344_value(br, row, names, fallback=np.nan):
    for name in names:
        try:
            if br is not None and name in br.index:
                v = safe_float(br.get(name), np.nan)
                if pd.notna(v):
                    return v
        except Exception:
            pass
        try:
            v = safe_float(row.get(name), np.nan)
            if pd.notna(v):
                return v
        except Exception:
            pass
    return fallback


def _v344_baseline(row: pd.Series, br: Optional[pd.Series], market: str):
    vals = {
        "l5": _v344_value(br, row, [f"{market}_l5", "L5 Avg"]),
        "l10": _v344_value(br, row, [f"{market}_l10", "L10 Avg"]),
        "l20": _v344_value(br, row, [f"{market}_l20", "L20 Avg"]),
        "season": _v344_value(br, row, [f"{market}_avg", "Season Avg"]),
        "prior": _v344_value(br, row, [f"{market}_prior"]),
    }
    available = _v344_numeric(vals.values())
    if not available:
        return safe_float(row.get("Projection"), np.nan), vals
    med = float(np.median(available))
    for k in vals:
        if pd.isna(vals[k]):
            vals[k] = med
    # L5 is intentionally capped in influence. L10/L20/season establish the
    # sustainable level; prior protects small samples and rookies.
    anchor = (
        0.16 * vals["l5"]
        + 0.26 * vals["l10"]
        + 0.22 * vals["l20"]
        + 0.29 * vals["season"]
        + 0.07 * vals["prior"]
    )
    # Winsorize the anchor around the robust center of all windows.
    mad = float(np.median(np.abs(np.asarray(available) - med))) if available else 0.0
    width = max({"PTS": 2.8, "REB": 1.25, "AST": 1.15, "PRA": 4.2}.get(market, 2.0), 2.5 * mad)
    anchor = float(np.clip(anchor, max(0.0, med - width), med + width))
    return anchor, vals


def _v344_minutes_multiplier(row: pd.Series, br: Optional[pd.Series]) -> tuple:
    projected = safe_float(row.get("MIN Proj"), np.nan)
    l5 = _v344_value(br, row, ["MIN_l5"])
    l10 = _v344_value(br, row, ["MIN_l10"])
    season = _v344_value(br, row, ["MIN_avg", "MIN"])
    recent = _v344_numeric([l5, l10, season])
    if pd.isna(projected) or not recent:
        return 1.0, 55.0
    baseline = 0.35*(l5 if pd.notna(l5) else np.median(recent)) + 0.40*(l10 if pd.notna(l10) else np.median(recent)) + 0.25*(season if pd.notna(season) else np.median(recent))
    if baseline <= 0:
        return 1.0, 55.0
    raw = projected / baseline
    dispersion = float(np.std(recent)) if len(recent) >= 2 else 2.5
    confidence = float(np.clip(96.0 - dispersion*8.0 - abs(projected-baseline)*2.2, 45.0, 96.0))
    # Only a verified role change may move the projection by more than 4%.
    role_text = " ".join(str(row.get(c, "")) for c in ["Injury Status", "Role", "Starter Status", "Lineup Status", "Availability"] ).upper()
    verified_change = any(t in role_text for t in ["CONFIRMED START", "STARTER", "OUT", "INACTIVE", "ROLE CHANGE"])
    cap = 0.06 if verified_change and confidence >= 75 else 0.04
    return float(np.clip(raw, 1-cap, 1+cap)), confidence


def _v344_matchup_multiplier(row: pd.Series) -> tuple:
    integrity = str(row.get("Data Integrity", "LIMITED")).upper()
    opp = str(row.get("Opponent", "")).strip()
    drtg = safe_float(row.get("Opponent DRtg"), np.nan)
    pace = safe_float(row.get("Opponent Pace"), np.nan)
    rank = safe_float(row.get("Opponent Market Rank"), np.nan)
    teams = safe_float(row.get("Opponent Market Rank Teams"), np.nan)
    score = safe_float(row.get("Opponent Matchup Score"), 50.0)
    verified = integrity == "VERIFIED" and opp and opp.lower() not in {"nan", "none", "opponent unavailable"} and pd.notna(drtg) and pd.notna(pace) and pd.notna(rank)
    if not verified:
        return 1.0, "Unknown", 35.0
    # The upstream matchup score already combines pace/DRtg/position context.
    # Apply one small bounded move only. Rank is used as confirmation, not a
    # second boost.
    score_move = float(np.clip((score - 50.0) / 50.0 * 0.0125, -0.0125, 0.0125))
    rank_move = 0.0
    if pd.notna(teams) and teams >= 6:
        pct = (rank - 1.0) / max(1.0, teams - 1.0)
        rank_move = float(np.clip((pct - 0.5) * 0.005, -0.0025, 0.0025))
    mult = float(np.clip(1.0 + score_move + rank_move, 0.985, 1.015))
    grade = "Favorable" if score >= 58 else "Tough" if score <= 42 else "Neutral"
    confidence = float(np.clip(70 + min(20, teams if pd.notna(teams) else 0), 70, 92))
    return mult, grade, confidence


def _v344_market_shrink(proj: float, line: float, integrity: str, sample_quality: float) -> tuple:
    if pd.isna(proj) or pd.isna(line):
        return proj, 0.0
    # Sportsbook consensus is informative but never replaces the model.
    # Verified/high-sample projections receive less market shrinkage.
    base_w = 0.12 if integrity == "VERIFIED" else 0.22
    w = float(np.clip(base_w + (1.0-sample_quality)*0.10, 0.10, 0.30))
    return float((1.0-w)*proj + w*line), w


def _v344_component_projection(row: pd.Series, br: Optional[pd.Series], market: str):
    anchor, vals = _v344_baseline(row, br, market)
    if pd.isna(anchor):
        return np.nan, vals, {}
    min_mult, min_conf = _v344_minutes_multiplier(row, br)
    matchup_mult, matchup_grade, matchup_conf = _v344_matchup_multiplier(row)
    raw = anchor * min_mult * matchup_mult
    # Robust sanity cap around L10/L20/season; this is not a market cap.
    stable = _v344_numeric([vals.get("l10"), vals.get("l20"), vals.get("season"), vals.get("prior")])
    if stable:
        center = float(np.median(stable))
        sd_proxy = float(np.std(stable)) if len(stable) >= 2 else 0.0
        width = max({"PTS":3.2,"REB":1.45,"AST":1.35,"PRA":4.8}.get(market,2.5), 2.25*sd_proxy)
        raw = float(np.clip(raw, max(0.0, center-width), center+width))
    line = safe_float(row.get("Line"), np.nan)
    sample_n = safe_float(_v344_value(br, row, [f"{market}_Games", "Games", "GP"]), 15.0)
    sample_quality = float(np.clip(sample_n/25.0, 0.35, 1.0))
    integrity = str(row.get("Data Integrity", "LIMITED")).upper()
    final, market_w = _v344_market_shrink(raw, line, integrity, sample_quality)
    meta = {
        "anchor": anchor, "minutes_mult": min_mult, "minutes_conf": min_conf,
        "matchup_mult": matchup_mult, "matchup_grade": matchup_grade,
        "matchup_conf": matchup_conf, "market_weight": market_w,
        "sample_quality": sample_quality,
    }
    return final, vals, meta


def _v344_sd(br: Optional[pd.Series], market: str, projection: float, data_conf: float) -> float:
    default = {"PTS":4.9,"REB":2.45,"AST":2.25,"PRA":6.8}.get(market,4.0)
    sd = _v344_value(br, pd.Series(dtype=object), [f"{market}_Std20", f"{market}_std"], default)
    floor = {"PTS":3.6,"REB":1.65,"AST":1.55,"PRA":5.1}.get(market,2.2)
    ceiling = {"PTS":7.8,"REB":4.5,"AST":4.2,"PRA":11.5}.get(market,8.0)
    # Missing/limited data increases uncertainty rather than shifting the mean.
    uncertainty = 1.0 + max(0.0, 82.0-data_conf)/100.0
    return float(np.clip(sd*uncertainty, floor, ceiling))


def _v344_probability(line: float, mean: float, sd: float) -> float:
    if pd.isna(line) or pd.isna(mean) or pd.isna(sd) or sd <= 0:
        return 50.0
    # Half-point continuity correction prevents tiny edges from looking too strong.
    return float(np.clip(_normal_over_probability(line + 0.15, mean, sd), 1.0, 99.0))


def _v344_rebuild_board(board: pd.DataFrame, base: pd.DataFrame) -> pd.DataFrame:
    if board is None or board.empty:
        return board
    lookup = _v344_player_lookup(base)
    rows = []
    component_cache = {}
    for _, rr in board.iterrows():
        row = rr.copy()
        key = normalize_name(row.get("Matched Player") or row.get("Player"))
        br = lookup.loc[key] if (not lookup.empty and key in lookup.index) else None
        market = str(row.get("Market", "PTS")).upper()
        cache_key = (key, str(row.get("Team", "")), str(row.get("Opponent", "")), safe_float(row.get("MIN Proj"), np.nan))
        if cache_key not in component_cache:
            comps, values, metas = {}, {}, {}
            for m in ["PTS","REB","AST"]:
                p, v, meta = _v344_component_projection(row, br, m)
                comps[m], values[m], metas[m] = p, v, meta
            component_cache[cache_key] = (comps, values, metas)
        comps, values, metas = component_cache[cache_key]

        if market == "PRA" and all(pd.notna(comps.get(m)) for m in ["PTS","REB","AST"]):
            # Exact component identity: no second PRA matchup, pace, minutes or cap.
            final_proj = float(comps["PTS"] + comps["REB"] + comps["AST"])
            vals = {k: sum(safe_float(values[m].get(k),0.0) for m in ["PTS","REB","AST"]) for k in ["l5","l10","l20","season","prior"]}
            meta = {
                "anchor": sum(safe_float(metas[m].get("anchor"),0.0) for m in metas),
                "minutes_mult": float(np.mean([metas[m].get("minutes_mult",1.0) for m in metas])),
                "minutes_conf": float(np.mean([metas[m].get("minutes_conf",55.0) for m in metas])),
                "matchup_mult": float(np.mean([metas[m].get("matchup_mult",1.0) for m in metas])),
                "matchup_grade": metas["PTS"].get("matchup_grade","Unknown"),
                "matchup_conf": float(np.mean([metas[m].get("matchup_conf",35.0) for m in metas])),
                "market_weight": float(np.mean([metas[m].get("market_weight",0.0) for m in metas])),
                "sample_quality": float(np.mean([metas[m].get("sample_quality",0.5) for m in metas])),
            }
        else:
            final_proj = comps.get(market, np.nan)
            vals = values.get(market, {})
            meta = metas.get(market, {})

        line = safe_float(row.get("Line"), np.nan)
        edge = final_proj-line if pd.notna(final_proj) and pd.notna(line) else np.nan
        integrity = str(row.get("Data Integrity", "LIMITED")).upper()
        data_conf = 94.0 if integrity == "VERIFIED" else 64.0
        final_conf = float(np.clip(0.36*data_conf + 0.32*meta.get("minutes_conf",55) + 0.18*meta.get("matchup_conf",35) + 0.14*(meta.get("sample_quality",.5)*100), 35, 96))
        sd = _v344_sd(br, market, final_proj, final_conf)
        overp = _v344_probability(line, final_proj, sd)
        underp = 100.0-overp

        # Meaningful direction thresholds. A tiny positive projection difference is
        # NEUTRAL, not an OVER. These are roughly 0.15–0.25 SD by market.
        neutral_edge = {"PTS":0.75,"REB":0.40,"AST":0.40,"PRA":1.25}.get(market,0.75)
        min_prob = 54.5
        if pd.isna(edge):
            lean = "PASS"
        elif edge >= neutral_edge and overp >= min_prob:
            lean = "OVER"
        elif edge <= -neutral_edge and underp >= min_prob:
            lean = "UNDER"
        else:
            lean = "NEUTRAL"
        sidep = overp if lean == "OVER" else underp if lean == "UNDER" else max(overp, underp)

        baseline_list = _v344_numeric([vals.get("l5"),vals.get("l10"),vals.get("l20"),vals.get("season")]) if isinstance(vals,dict) else []
        recent_votes = 0
        if pd.notna(line) and lean in {"OVER","UNDER"}:
            recent_votes = sum(1 for x in baseline_list if (x>line)==(lean=="OVER"))

        edge_scale = {"PTS":6.0,"REB":11.0,"AST":11.0,"PRA":3.8}.get(market,6.0)
        edge_score = float(np.clip(50 + abs(edge if pd.notna(edge) else 0)*edge_scale, 0, 100))
        hit_score = float(np.clip(0.46*sidep + 0.24*final_conf + 0.16*edge_score + 0.14*(40+recent_votes*13), 0, 100))

        official_edge = {"PTS":1.50,"REB":0.75,"AST":0.75,"PRA":2.25}.get(market,1.25)
        official_prob = {"PTS":60.0,"REB":59.0,"AST":59.0,"PRA":60.0}.get(market,60.0)
        reasons = []
        if lean not in {"OVER","UNDER"}: reasons.append("edge inside neutral/no-play zone")
        if integrity != "VERIFIED": reasons.append("opponent/data context not fully verified")
        if pd.isna(edge) or abs(edge) < official_edge: reasons.append("edge below official threshold")
        if sidep < official_prob: reasons.append("calibrated probability below official threshold")
        if recent_votes < 2: reasons.append("recent/season support is weak")
        if final_conf < 78: reasons.append("projection confidence below 78%")
        official = "PASS" if reasons else ("🔥 OVER" if lean=="OVER" else "⚠️ UNDER")

        row["Projection Before Calibration"] = safe_float(row.get("Projection"), np.nan)
        row["Projection"] = round(final_proj,2) if pd.notna(final_proj) else np.nan
        row["Edge"] = round(edge,2) if pd.notna(edge) else np.nan
        row["Lean"] = lean
        row["Over %"] = round(overp,1)
        row["Under %"] = round(underp,1)
        row["Hit Score"] = round(hit_score,1)
        row["Official Play Score"] = round(hit_score,1)
        row["Official"] = official
        row["Tier"] = "S" if official!="PASS" and hit_score>=86 else "A" if official!="PASS" and hit_score>=78 else "B" if official!="PASS" else "TRACK"
        row["PASS Reason"] = " · ".join(dict.fromkeys(reasons))
        row["Opponent Matchup Grade"] = meta.get("matchup_grade","Unknown")
        row["Matchup Multiplier Applied"] = round(meta.get("matchup_mult",1.0),4)
        row["Minutes Multiplier Applied"] = round(meta.get("minutes_mult",1.0),4)
        row["Minutes Confidence"] = round(meta.get("minutes_conf",55.0),1)
        row["Matchup Confidence"] = round(meta.get("matchup_conf",35.0),1)
        row["Final Projection Confidence"] = round(final_conf,1)
        row["Market Shrink Weight"] = round(meta.get("market_weight",0.0),3)
        row["Simulation SD"] = round(sd,2)
        row["Projection Audit"] = "L10/L20/season-led Bayesian baseline → bounded minutes once → verified matchup once (max ±1.5%) → small market shrink → uncertainty-calibrated simulation → neutral zone"
        if market == "PRA":
            row["PRA Component PTS"] = round(comps["PTS"],2)
            row["PRA Component REB"] = round(comps["REB"],2)
            row["PRA Component AST"] = round(comps["AST"],2)
            row["PRA Component Sum"] = round(comps["PTS"]+comps["REB"]+comps["AST"],2)
            row["PRA Identity Check"] = abs(final_proj-(comps["PTS"]+comps["REB"]+comps["AST"])) < 0.005
        rows.append(row)

    out = pd.DataFrame(rows)
    actionable = out[out["Lean"].isin(["OVER","UNDER"])]
    overs = int((actionable["Lean"]=="OVER").sum())
    unders = int((actionable["Lean"]=="UNDER").sum())
    neutrals = int((out["Lean"]=="NEUTRAL").sum())
    total = len(actionable)
    over_rate = overs/max(1,total)
    warning = "BALANCED"
    if total >= 8 and over_rate >= .75:
        warning = f"OVER-SKEW WARNING: {overs}/{total} actionable projections lean over. This is a diagnostic—not an automatic side reversal."
    elif total >= 8 and over_rate <= .25:
        warning = f"UNDER-SKEW WARNING: {unders}/{total} actionable projections lean under. This is a diagnostic—not an automatic side reversal."
    summary = {"overs":overs,"unders":unders,"neutrals":neutrals,"total":total,"over_rate":over_rate,"warning":warning}
    st.session_state["wnba_slate_bias_summary"] = summary
    out["Slate Over Count"] = overs
    out["Slate Under Count"] = unders
    out["Slate Neutral Count"] = neutrals
    out["Slate Bias Warning"] = warning
    out = out.sort_values(["Official Play Score","Hit Score","Edge"], ascending=[False,False,False])
    save_dataset("projection_board", out)
    return out


def _historical_make_projection_board_7(lines, logs, base, mode: Optional[str] = None):
    board = _make_projection_board_v344_input(lines, logs, base, mode)
    return _v344_rebuild_board(board, base)


_render_grouped_player_board_v344_input = render_grouped_player_board

def render_grouped_player_board(mode: str, use_ud_flag: bool, logs_global: pd.DataFrame, master_global: pd.DataFrame):
    _render_grouped_player_board_v344_input(mode, use_ud_flag, logs_global, master_global)
    summary = st.session_state.get("wnba_slate_bias_summary", {})
    warning = str(summary.get("warning", ""))
    if warning and warning != "BALANCED":
        st.warning(warning)
    elif summary:
        st.caption(f"Slate direction: {summary.get('overs',0)} overs / {summary.get('unders',0)} unders / {summary.get('neutrals',0)} neutral-no plays.")




# ================================================================
# v3.4.7 DOUBLE-CHECKED FINAL-SIDE PIPELINE + SLATE TRACKER
# The previous calibrated board was being modified again by downstream
# matchup/team-context enrichers. This finalizer runs LAST, after all
# enrichments, and is the only authority for Projection/Lean/Probability.
# ================================================================

def _v345_num(v, default=np.nan):
    try:
        x = float(v)
        return x if np.isfinite(x) else default
    except Exception:
        return default


def _v345_norm_over(line: float, mean: float, sd: float) -> float:
    if pd.isna(line) or pd.isna(mean) or pd.isna(sd) or sd <= 0:
        return 50.0
    try:
        from math import erf, sqrt
        z = ((line + 0.15) - mean) / max(0.25, sd)
        return float(np.clip(100.0 * 0.5 * (1.0 - erf(z / sqrt(2.0))), 1.0, 99.0))
    except Exception:
        return 50.0


def _v345_market_sd(row: pd.Series, market: str, final_proj: float) -> float:
    defaults = {"PTS": 4.8, "REB": 2.35, "AST": 2.15, "PRA": 6.6}
    floors = {"PTS": 3.8, "REB": 1.70, "AST": 1.60, "PRA": 5.2}
    caps = {"PTS": 7.8, "REB": 4.4, "AST": 4.1, "PRA": 11.0}
    vals = [_v345_num(row.get(c)) for c in ["L5 Avg", "L10 Avg", "L20 Avg", "Season Avg"]]
    vals = [x for x in vals if pd.notna(x)]
    dispersion = float(np.std(vals)) if len(vals) >= 2 else 0.0
    sd = max(defaults.get(market, 4.0), dispersion * 1.35)
    if str(row.get("Data Integrity", "LIMITED")).upper() != "VERIFIED":
        sd *= 1.12
    return float(np.clip(sd, floors.get(market, 2.0), caps.get(market, 8.0)))


def _v345_sustainable_projection(row: pd.Series) -> float:
    market = str(row.get("Market", "PTS")).upper()
    l5 = _v345_num(row.get("L5 Avg"))
    l10 = _v345_num(row.get("L10 Avg"))
    l20 = _v345_num(row.get("L20 Avg"))
    season = _v345_num(row.get("Season Avg"))
    raw_source = row.get("Projection Before Final Side Fix") if "Projection Before Final Side Fix" in row.index else row.get("Projection")
    raw = _v345_num(raw_source)
    if pd.isna(raw):
        raw = _v345_num(row.get("Projection"))
    available = [x for x in [l5, l10, l20, season, raw] if pd.notna(x)]
    if not available:
        return np.nan
    med = float(np.median(available))
    l5 = med if pd.isna(l5) else l5
    l10 = med if pd.isna(l10) else l10
    l20 = l10 if pd.isna(l20) else l20
    season = med if pd.isna(season) else season
    raw = med if pd.isna(raw) else raw

    # Long-term opportunity is the anchor. L5 can move the number, but cannot
    # dominate it. The upstream model remains a small signal for real role news.
    if market == "PTS":
        baseline = 0.14*l5 + 0.34*l10 + 0.16*l20 + 0.36*season
    elif market in {"REB", "AST"}:
        baseline = 0.12*l5 + 0.32*l10 + 0.16*l20 + 0.40*season
    else:  # PRA fallback when components are not all listed
        baseline = 0.14*l5 + 0.34*l10 + 0.16*l20 + 0.36*season

    role_text = " ".join(str(row.get(c, "")) for c in [
        "Injury Status", "Role", "Starter Status", "Lineup Status", "Availability",
        "Injury Context Note", "Projected Rotation Note"
    ]).upper()
    verified_role_change = any(t in role_text for t in [
        "CONFIRMED START", "NEW STARTER", "ROLE CHANGE", "STARTING IN PLACE"
    ]) and "QUESTIONABLE" not in role_text
    raw_weight = 0.30 if verified_role_change else 0.15
    final = (1.0-raw_weight)*baseline + raw_weight*raw

    # Apply opponent context exactly once here. The move is deliberately small.
    integrity = str(row.get("Data Integrity", "LIMITED")).upper()
    score = _v345_num(row.get("Opponent Matchup Score"), 50.0)
    opp = str(row.get("Opponent", "")).strip().lower()
    verified = integrity == "VERIFIED" and opp not in {"", "nan", "none", "opponent unavailable"}
    matchup_move = 0.0
    if verified:
        matchup_move = float(np.clip((score-50.0)/50.0 * 0.010, -0.010, 0.010))
    final *= (1.0 + matchup_move)

    # Robust cap around L10/season protects against duplicated upstream boosts.
    center = 0.55*l10 + 0.45*season
    width = {"PTS": 3.0, "REB": 1.30, "AST": 1.20, "PRA": 4.4}.get(market, 2.5)
    final = float(np.clip(final, max(0.0, center-width), center+width))
    return final



# ================================================================
# v3.4.8 EVIDENCE-BOUNDED CONTEXT LAYERS
# Adds role/opportunity context without rewriting the calibrated core.
# Every projection change is symmetric, data-gated, auditable, and capped.
# ================================================================

def _v348_first_num(row: pd.Series, names, default=np.nan):
    for name in names:
        try:
            value = _v345_num(row.get(name))
            if pd.notna(value):
                return value
        except Exception:
            pass
    return default


def _v348_text(row: pd.Series, names) -> str:
    return " ".join(str(row.get(name, "")) for name in names).upper()


def _v348_role_verified(row: pd.Series) -> bool:
    txt = _v348_text(row, [
        "Injury Status", "Availability", "Lineup Status", "Starter Status",
        "Role", "Injury Context Note", "Projected Rotation Note"
    ])
    positive = any(tag in txt for tag in [
        "CONFIRMED START", "NEW STARTER", "STARTING IN PLACE", "ROLE CHANGE",
        "TEAMMATE OUT", "USAGE BUMP", "MINUTES BUMP"
    ])
    uncertain = any(tag in txt for tag in ["QUESTIONABLE", "GTD", "GAME TIME DECISION", "MINUTES LIMIT"])
    return positive and not uncertain


def _v348_blowout_context(row: pd.Series, projected_minutes: float) -> dict:
    spread = _v348_first_num(row, ["Spread", "Game Spread", "Vegas Spread", "Team Spread", "Market Spread"])
    existing = _v348_first_num(row, ["Blowout Risk", "Blowout Risk %", "BlowoutRisk", "Blowout Probability"])
    if pd.notna(existing):
        risk = existing * 100.0 if 0 <= existing <= 1 else existing
    elif pd.notna(spread):
        # Smooth probability proxy: near pick'em ~10%; 10+ point spread ~45%.
        risk = float(np.clip(8.0 + abs(spread) * 3.7, 8.0, 55.0))
    else:
        risk = 15.0
    star_minutes = pd.notna(projected_minutes) and projected_minutes >= 28
    # Expected-minute tax only; never a direct stat-rate penalty.
    minute_tax = 0.0
    if star_minutes and risk >= 45:
        minute_tax = -0.025
    elif star_minutes and risk >= 32:
        minute_tax = -0.012
    note = "High blowout watch" if risk >= 45 else "Moderate blowout watch" if risk >= 32 else "Low/neutral blowout risk"
    return {"risk": float(np.clip(risk, 0, 100)), "minute_tax": minute_tax, "note": note}


def _v348_minutes_context(row: pd.Series) -> dict:
    current = _v348_first_num(row, ["MIN Proj", "Projected Minutes", "Minutes Projection"])
    l3 = _v348_first_num(row, ["MIN_l3", "Minutes L3", "L3 Minutes"])
    l5 = _v348_first_num(row, ["MIN_l5", "Minutes L5", "L5 Minutes"])
    l10 = _v348_first_num(row, ["MIN_l10", "Minutes L10", "L10 Minutes"])
    season = _v348_first_num(row, ["MIN_avg", "Season Minutes", "MIN", "Minutes Avg"])
    vals = [v for v in [l3, l5, l10, season, current] if pd.notna(v) and v > 0]
    if not vals:
        return {"minutes": current, "factor": 1.0, "confidence": 45.0, "blowout": _v348_blowout_context(row, current), "note": "No reliable minute history"}
    med = float(np.median(vals))
    l3 = med if pd.isna(l3) else l3
    l5 = med if pd.isna(l5) else l5
    l10 = med if pd.isna(l10) else l10
    season = med if pd.isna(season) else season
    current = med if pd.isna(current) else current
    predicted = 0.16*l3 + 0.34*l5 + 0.32*l10 + 0.18*season
    if _v348_role_verified(row):
        predicted = 0.68*predicted + 0.32*current
    else:
        predicted = 0.84*predicted + 0.16*current
    blow = _v348_blowout_context(row, predicted)
    predicted *= (1.0 + blow["minute_tax"])
    dispersion = float(np.std([l3, l5, l10, season]))
    confidence = float(np.clip(96.0 - 7.5*dispersion - abs(current-predicted)*1.8, 45, 96))
    baseline = max(1.0, 0.40*l10 + 0.35*l5 + 0.25*season)
    raw_factor = predicted / baseline
    cap = 0.055 if _v348_role_verified(row) and confidence >= 75 else 0.035
    factor = float(np.clip(raw_factor, 1-cap, 1+cap))
    return {"minutes": float(np.clip(predicted, 4, 40.5)), "factor": factor, "confidence": confidence, "blowout": blow, "note": f"L3/L5/L10/season rotation blend; {blow['note']}"}


def _v348_usage_context(row: pd.Series, market: str) -> dict:
    # Prefer true usage fields; fall back to possession-volume proxies.
    u3 = _v348_first_num(row, ["USG_l3", "Usage L3", "L3 Usage", "USG% L3"])
    u5 = _v348_first_num(row, ["USG_l5", "Usage L5", "L5 Usage", "USG% L5", "usage_roll5"])
    u10 = _v348_first_num(row, ["USG_l10", "Usage L10", "L10 Usage", "USG% L10"])
    useason = _v348_first_num(row, ["USG%", "Usage", "Season Usage", "Usage Proxy"])
    vals = [v for v in [u3,u5,u10,useason] if pd.notna(v) and v > 0]
    if market not in {"PTS","AST","PRA"} or len(vals) < 2:
        return {"factor":1.0,"confidence":45.0,"trend":0.0,"note":"Usage neutral / unavailable"}
    med=float(np.median(vals))
    u3=med if pd.isna(u3) else u3; u5=med if pd.isna(u5) else u5; u10=med if pd.isna(u10) else u10; useason=med if pd.isna(useason) else useason
    recent=0.20*u3+0.38*u5+0.42*u10
    baseline=max(0.1,0.60*u10+0.40*useason)
    trend=(recent-baseline)/baseline
    cap=0.045 if _v348_role_verified(row) else 0.025
    # AST is less directly usage-driven than scoring.
    sensitivity=0.70 if market=="AST" else 1.0
    factor=float(np.clip(1.0+trend*sensitivity,1-cap,1+cap))
    dispersion=float(np.std([u3,u5,u10,useason]))
    confidence=float(np.clip(90-dispersion*2.5,45,92))
    return {"factor":factor,"confidence":confidence,"trend":trend,"note":f"Recent usage {'up' if trend>0.02 else 'down' if trend<-0.02 else 'stable'} ({trend:+.1%})"}


def _v348_possession_context(row: pd.Series) -> dict:
    game_pace = _v348_first_num(row, ["Projected Pace", "Game Pace", "Pace Projection", "Expected Possessions"])
    team_pace = _v348_first_num(row, ["Team Pace", "Own Team Pace"])
    opp_pace = _v348_first_num(row, ["Opponent Pace", "Opp Pace"])
    league = _v348_first_num(row, ["League Pace", "League Avg Pace"], 80.0)
    vals=[v for v in [game_pace,team_pace,opp_pace] if pd.notna(v) and v>0]
    if not vals or pd.isna(league) or league<=0:
        return {"factor":1.0,"possessions":np.nan,"note":"Possession pace neutral"}
    projected = game_pace if pd.notna(game_pace) else float(np.mean(vals))
    # Normalize NBA-style 95–105 values to WNBA 76–84 scale if necessary.
    if projected > 90 and league <= 90:
        projected *= 0.80
    factor=float(np.clip(projected/league,0.985,1.015))
    return {"factor":factor,"possessions":projected,"note":f"Projected game pace {projected:.1f}"}


def _v348_shot_volume_context(row: pd.Series, market: str, minutes: float) -> dict:
    if market not in {"PTS","PRA"}:
        return {"factor":1.0,"fga":np.nan,"three_pa":np.nan,"fta":np.nan,"note":"Shot-volume layer not used"}
    fga5=_v348_first_num(row,["FGA_l5","FGA L5","L5 FGA"])
    fga10=_v348_first_num(row,["FGA_l10","FGA L10","L10 FGA"])
    fgaseason=_v348_first_num(row,["FGA_avg","Season FGA","FGA"])
    three5=_v348_first_num(row,["3PA_l5","3PA L5","L5 3PA"])
    three10=_v348_first_num(row,["3PA_l10","3PA L10","L10 3PA"])
    threeseason=_v348_first_num(row,["3PA_avg","Season 3PA","3PA"])
    fta5=_v348_first_num(row,["FTA_l5","FTA L5","L5 FTA"])
    fta10=_v348_first_num(row,["FTA_l10","FTA L10","L10 FTA"])
    ftaseason=_v348_first_num(row,["FTA_avg","Season FTA","FTA"])
    fgas=[v for v in [fga5,fga10,fgaseason] if pd.notna(v) and v>=0]
    if len(fgas)<2:
        return {"factor":1.0,"fga":_v348_first_num(row,["Projected FGA","FGA Projection"]),"three_pa":np.nan,"fta":np.nan,"note":"Shot volume neutral / limited"}
    med=float(np.median(fgas)); fga5=med if pd.isna(fga5) else fga5; fga10=med if pd.isna(fga10) else fga10; fgaseason=med if pd.isna(fgaseason) else fgaseason
    projected_fga=0.36*fga5+0.40*fga10+0.24*fgaseason
    baseline=max(0.5,0.58*fga10+0.42*fgaseason)
    volume_trend=(projected_fga-baseline)/baseline
    cap=0.035 if _v348_role_verified(row) else 0.022
    factor=float(np.clip(1.0+volume_trend,1-cap,1+cap))
    def blend(a,b,c):
        vals=[v for v in [a,b,c] if pd.notna(v)]
        if not vals: return np.nan
        m=float(np.median(vals)); a=m if pd.isna(a) else a; b=m if pd.isna(b) else b; c=m if pd.isna(c) else c
        return 0.36*a+0.40*b+0.24*c
    return {"factor":factor,"fga":projected_fga,"three_pa":blend(three5,three10,threeseason),"fta":blend(fta5,fta10,ftaseason),"note":f"Shot volume {'up' if volume_trend>0.02 else 'down' if volume_trend<-0.02 else 'stable'} ({volume_trend:+.1%})"}


def _v348_rebound_context(row: pd.Series, market: str) -> dict:
    if market not in {"REB","PRA"}:
        return {"factor":1.0,"note":"Rebound-opportunity layer not used"}
    chances5=_v348_first_num(row,["Rebound Chances L5","REB Chances L5","ReboundChances_l5"])
    chances10=_v348_first_num(row,["Rebound Chances L10","REB Chances L10","ReboundChances_l10"])
    chances_season=_v348_first_num(row,["Rebound Chances","Season Rebound Chances","ReboundChances_avg"])
    opp_fg=_v348_first_num(row,["Opponent FG%","Opp FG%","Opponent eFG%"])
    opp_reb_rank=_v348_first_num(row,["Opponent REB Rank","REB Market Rank"])
    teams=_v348_first_num(row,["Opponent Market Rank Teams","Teams Ranked"],13)
    vals=[v for v in [chances5,chances10,chances_season] if pd.notna(v) and v>=0]
    trend=0.0
    if len(vals)>=2:
        med=float(np.median(vals)); chances5=med if pd.isna(chances5) else chances5; chances10=med if pd.isna(chances10) else chances10; chances_season=med if pd.isna(chances_season) else chances_season
        recent=0.42*chances5+0.58*chances10
        base=max(0.5,0.58*chances10+0.42*chances_season)
        trend=(recent-base)/base
    miss_env=0.0
    if pd.notna(opp_fg):
        fg=opp_fg/100.0 if opp_fg>1 else opp_fg
        miss_env=float(np.clip((0.445-fg)*0.18,-0.010,0.010))
    rank_env=0.0
    if pd.notna(opp_reb_rank) and pd.notna(teams) and teams>=6:
        pct=(opp_reb_rank-1)/max(1,teams-1)
        rank_env=float(np.clip((pct-0.5)*0.018,-0.009,0.009))
    factor=float(np.clip(1.0+trend*0.45+miss_env+rank_env,0.975,1.025))
    return {"factor":factor,"note":f"Rebound chances trend {trend:+.1%}; miss/rank environment bounded"}


def _v348_volatility_context(row: pd.Series, market: str) -> dict:
    vals=[_v345_num(row.get(c)) for c in ["L5 Avg","L10 Avg","L20 Avg","Season Avg"]]
    vals=[v for v in vals if pd.notna(v)]
    if len(vals)<2:
        return {"score":70.0,"tier":"MEDIUM","sd_mult":1.08,"confidence_tax":5.0}
    mean=max(0.5,float(np.mean(vals))); cv=float(np.std(vals)/mean)
    score=float(np.clip(35+cv*180,25,95))
    tier="HIGH" if score>=72 else "LOW" if score<=45 else "MEDIUM"
    sd_mult=1.16 if tier=="HIGH" else 0.96 if tier=="LOW" else 1.04
    confidence_tax=8.0 if tier=="HIGH" else 0.0 if tier=="LOW" else 3.0
    return {"score":score,"tier":tier,"sd_mult":sd_mult,"confidence_tax":confidence_tax}


def _v348_market_intelligence(row: pd.Series, projection: float) -> dict:
    line=_v345_num(row.get("Line")); open_line=_v348_first_num(row,["Opening Line","Open Line","Line Open"])
    consensus=_v348_first_num(row,["Consensus Line","Market Consensus","Median Market Line"])
    current_ref=consensus if pd.notna(consensus) else line
    disagreement=projection-current_ref if pd.notna(projection) and pd.notna(current_ref) else np.nan
    movement=(line-open_line) if pd.notna(line) and pd.notna(open_line) else np.nan
    flag="NORMAL"
    tax=0.0
    if pd.notna(disagreement) and abs(disagreement)>=5:
        flag="LARGE MODEL/MARKET DISAGREEMENT"; tax=7.0
    elif pd.notna(disagreement) and abs(disagreement)>=3:
        flag="MODERATE MODEL/MARKET DISAGREEMENT"; tax=3.5
    return {"disagreement":disagreement,"movement":movement,"flag":flag,"confidence_tax":tax}


def _v348_enhance_projection(row: pd.Series, base_projection: float, market: str) -> tuple:
    if pd.isna(base_projection):
        return base_projection, {}
    minutes=_v348_minutes_context(row)
    usage=_v348_usage_context(row,market)
    poss=_v348_possession_context(row)
    shots=_v348_shot_volume_context(row,market,minutes.get("minutes",np.nan))
    reb=_v348_rebound_context(row,market)
    # Multiplicative modules are combined in log space and globally capped.
    factors=[minutes["factor"],usage["factor"],poss["factor"],shots["factor"],reb["factor"]]
    log_move=sum(float(np.log(max(0.85,min(1.15,f)))) for f in factors if pd.notna(f))
    total_cap=0.070 if _v348_role_verified(row) else 0.045
    total_factor=float(np.exp(np.clip(log_move,np.log(1-total_cap),np.log(1+total_cap))))
    final=float(base_projection*total_factor)
    # Robust final guardrail around the already calibrated baseline.
    width={"PTS":2.4,"REB":1.0,"AST":0.95,"PRA":3.6}.get(market,2.0)
    final=float(np.clip(final,max(0.0,base_projection-width),base_projection+width))
    market_ctx=_v348_market_intelligence(row,final)
    vol=_v348_volatility_context(row,market)
    audit={
        "minutes":minutes,"usage":usage,"possession":poss,"shots":shots,"rebound":reb,
        "volatility":vol,"market":market_ctx,"total_factor":total_factor,
        "base_projection":base_projection,"final_projection":final,
    }
    return final,audit

def _v345_post_context_finalizer(board: pd.DataFrame, base: Optional[pd.DataFrame] = None) -> pd.DataFrame:
    if board is None or board.empty:
        return board
    out = board.copy()
    out["Projection Before Final Side Fix"] = pd.to_numeric(out.get("Projection"), errors="coerce")
    out["Projection"] = out.apply(_v345_sustainable_projection, axis=1)
    _v348_audits = {}
    for _idx, _r in out.iterrows():
        _market = str(_r.get("Market", "PTS")).upper()
        _base_proj = _v345_num(out.at[_idx, "Projection"])
        _final_proj, _audit = _v348_enhance_projection(_r, _base_proj, _market)
        out.at[_idx, "Projection"] = _final_proj
        _v348_audits[_idx] = _audit

    # PRA must equal the final displayed PTS + REB + AST whenever all components
    # are available for that player/team/opponent slate.
    group_cols = [c for c in ["Player", "Matched Player", "Team", "Opponent", "Slate", "SlateDate"] if c in out.columns]
    player_col = "Matched Player" if "Matched Player" in out.columns else "Player"
    group_cols = [player_col] + [c for c in ["Team", "Opponent", "Slate", "SlateDate"] if c in out.columns]
    for _, idx in out.groupby(group_cols, dropna=False).groups.items():
        sub = out.loc[idx]
        comp = {}
        for m in ["PTS", "REB", "AST"]:
            vals = pd.to_numeric(sub.loc[sub["Market"].astype(str).str.upper()==m, "Projection"], errors="coerce").dropna()
            if not vals.empty:
                comp[m] = float(vals.iloc[0])
        if len(comp) == 3:
            pra_idx = sub.index[sub["Market"].astype(str).str.upper()=="PRA"]
            if len(pra_idx):
                out.loc[pra_idx, "Projection"] = comp["PTS"] + comp["REB"] + comp["AST"]
                out.loc[pra_idx, "PRA Component PTS"] = comp["PTS"]
                out.loc[pra_idx, "PRA Component REB"] = comp["REB"]
                out.loc[pra_idx, "PRA Component AST"] = comp["AST"]
                out.loc[pra_idx, "PRA Component Sum"] = comp["PTS"] + comp["REB"] + comp["AST"]
                out.loc[pra_idx, "PRA Identity Check"] = True

    rows = []
    for _, rr in out.iterrows():
        row = rr.copy()
        market = str(row.get("Market", "PTS")).upper()
        audit = _v348_audits.get(row.name, {})
        proj = _v345_num(row.get("Projection"))
        line = _v345_num(row.get("Line"))
        edge = proj-line if pd.notna(proj) and pd.notna(line) else np.nan
        sd = _v345_market_sd(row, market, proj)
        vol_ctx = audit.get("volatility", {})
        sd = float(np.clip(sd * _v345_num(vol_ctx.get("sd_mult"), 1.0), 0.5, 15.0))
        overp = _v345_norm_over(line, proj, sd)
        underp = 100.0-overp

        neutral_edge = {"PTS":0.90,"REB":0.50,"AST":0.50,"PRA":1.50}.get(market,0.90)
        min_prob = 54.0
        if pd.isna(edge):
            lean = "PASS"
        elif edge >= neutral_edge and overp >= min_prob:
            lean = "OVER"
        elif edge <= -neutral_edge and underp >= min_prob:
            lean = "UNDER"
        else:
            lean = "NEUTRAL"
        sidep = overp if lean=="OVER" else underp if lean=="UNDER" else max(overp,underp)

        integrity = str(row.get("Data Integrity", "LIMITED")).upper()
        baseline_vals = [_v345_num(row.get(c)) for c in ["L5 Avg","L10 Avg","L20 Avg","Season Avg"]]
        baseline_vals = [x for x in baseline_vals if pd.notna(x)]
        votes = sum(1 for x in baseline_vals if pd.notna(line) and ((x>line)==(lean=="OVER"))) if lean in {"OVER","UNDER"} else 0
        edge_score = float(np.clip(50 + abs(edge if pd.notna(edge) else 0)*{"PTS":7.0,"REB":12.0,"AST":12.0,"PRA":4.0}.get(market,7.0), 0, 100))
        data_score = 92.0 if integrity=="VERIFIED" else 62.0
        market_ctx = audit.get("market", {})
        confidence_tax = _v345_num(vol_ctx.get("confidence_tax"), 0.0) + _v345_num(market_ctx.get("confidence_tax"), 0.0)
        data_score = float(np.clip(data_score - confidence_tax, 35, 96))
        hit_score = float(np.clip(0.52*sidep + 0.20*edge_score + 0.16*data_score + 0.12*(40+votes*14), 0, 100))

        official_edge = {"PTS":1.60,"REB":0.85,"AST":0.85,"PRA":2.40}.get(market,1.50)
        official_prob = {"PTS":59.0,"REB":58.5,"AST":58.5,"PRA":59.0}.get(market,59.0)
        reasons=[]
        availability_text = " ".join(str(row.get(c, "")) for c in ["Injury Status","Availability","Lineup Status","Starter Status"]).upper()
        unavailable_player = any(tag in availability_text for tag in ["OUT","INACTIVE","DOUBTFUL","SUSPENDED"])
        if unavailable_player:
            lean = "PASS"
            sidep = max(overp, underp)
            reasons.append("player unavailable or doubtful")
        if lean not in {"OVER","UNDER"}: reasons.append("inside neutral/no-play zone")
        if integrity!="VERIFIED": reasons.append("data/opponent context not verified")
        if pd.isna(edge) or abs(edge)<official_edge: reasons.append("edge below official threshold")
        if sidep<official_prob: reasons.append("probability below official threshold")
        if votes<2: reasons.append("recent/season support is weak")
        blow_ctx = audit.get("minutes", {}).get("blowout", {})
        if _v345_num(blow_ctx.get("risk"), 0) >= 45 and market in {"PTS","PRA"}: reasons.append("high blowout/minutes volatility")
        if str(vol_ctx.get("tier", "MEDIUM")) == "HIGH" and sidep < 62: reasons.append("high player volatility")
        if str(market_ctx.get("flag", "NORMAL")) == "LARGE MODEL/MARKET DISAGREEMENT": reasons.append("large model/market disagreement")
        official = "PASS" if reasons else ("🔥 OVER" if lean=="OVER" else "⚠️ UNDER")

        row["Projection"] = round(proj,2) if pd.notna(proj) else np.nan
        row["Edge"] = round(edge,2) if pd.notna(edge) else np.nan
        row["Lean"] = lean
        row["Over %"] = round(overp,1)
        row["Under %"] = round(underp,1)
        row["Simulation SD"] = round(sd,2)
        row["Hit Score"] = round(hit_score,1)
        row["Official Play Score"] = round(hit_score,1)
        row["Official"] = official
        row["Tier"] = "S" if official!="PASS" and hit_score>=86 else "A" if official!="PASS" and hit_score>=78 else "B" if official!="PASS" else "TRACK"
        row["PASS Reason"] = " · ".join(dict.fromkeys(reasons))
        min_ctx = audit.get("minutes", {})
        usage_ctx = audit.get("usage", {})
        poss_ctx = audit.get("possession", {})
        shot_ctx = audit.get("shots", {})
        reb_ctx = audit.get("rebound", {})
        blow_ctx = min_ctx.get("blowout", {})
        row["Context Base Projection"] = round(_v345_num(audit.get("base_projection"), proj), 2)
        row["Context Total Multiplier"] = round(_v345_num(audit.get("total_factor"), 1.0), 4)
        row["Minutes 2.0 Projection"] = round(_v345_num(min_ctx.get("minutes")), 2) if pd.notna(_v345_num(min_ctx.get("minutes"))) else np.nan
        row["Minutes 2.0 Confidence"] = round(_v345_num(min_ctx.get("confidence"), 45), 1)
        row["Live Usage Factor"] = round(_v345_num(usage_ctx.get("factor"), 1.0), 4)
        row["Usage Trend"] = round(_v345_num(usage_ctx.get("trend"), 0.0), 4)
        row["Projected Possessions"] = round(_v345_num(poss_ctx.get("possessions")), 2) if pd.notna(_v345_num(poss_ctx.get("possessions"))) else np.nan
        row["Possession Factor"] = round(_v345_num(poss_ctx.get("factor"), 1.0), 4)
        row["Shot Volume Factor"] = round(_v345_num(shot_ctx.get("factor"), 1.0), 4)
        row["Projected FGA 2.0"] = round(_v345_num(shot_ctx.get("fga")), 2) if pd.notna(_v345_num(shot_ctx.get("fga"))) else np.nan
        row["Projected 3PA 2.0"] = round(_v345_num(shot_ctx.get("three_pa")), 2) if pd.notna(_v345_num(shot_ctx.get("three_pa"))) else np.nan
        row["Projected FTA 2.0"] = round(_v345_num(shot_ctx.get("fta")), 2) if pd.notna(_v345_num(shot_ctx.get("fta"))) else np.nan
        row["Rebound Opportunity Factor"] = round(_v345_num(reb_ctx.get("factor"), 1.0), 4)
        row["Blowout Risk %"] = round(_v345_num(blow_ctx.get("risk"), 15), 1)
        row["Blowout Note"] = str(blow_ctx.get("note", "Low/neutral blowout risk"))
        row["Volatility Score"] = round(_v345_num(vol_ctx.get("score"), 70), 1)
        row["Volatility Tier 2.0"] = str(vol_ctx.get("tier", "MEDIUM"))
        row["Market Disagreement"] = round(_v345_num(market_ctx.get("disagreement")), 2) if pd.notna(_v345_num(market_ctx.get("disagreement"))) else np.nan
        row["Market Intelligence Flag"] = str(market_ctx.get("flag", "NORMAL"))
        row["Context Explain"] = " | ".join([str(min_ctx.get("note","")), str(usage_ctx.get("note","")), str(poss_ctx.get("note","")), str(shot_ctx.get("note","")), str(reb_ctx.get("note",""))])
        row["Finalizer Version"] = "v3.4.8-context-layers-blowout"
        row["Projection Audit"] = "calibrated core preserved → bounded Minutes 2.0 → live usage → possessions → shot/rebound opportunity → blowout minutes risk → volatility/market confidence only → final neutral side gate"
        rows.append(row)

    out = pd.DataFrame(rows)
    actionable = out[out["Lean"].isin(["OVER","UNDER"])]
    overs = int((actionable["Lean"]=="OVER").sum())
    unders = int((actionable["Lean"]=="UNDER").sum())
    neutrals = int((out["Lean"]=="NEUTRAL").sum())
    total = len(actionable)
    rate = overs/max(1,total)
    warning = "BALANCED"
    if total>=8 and rate>=0.75:
        warning=f"OVER-SKEW WARNING: {overs}/{total} actionable. Review raw baselines; sides were not force-balanced."
    elif total>=8 and rate<=0.25:
        warning=f"UNDER-SKEW WARNING: {unders}/{total} actionable. Review raw baselines; sides were not force-balanced."
    st.session_state["wnba_slate_bias_summary"]={"overs":overs,"unders":unders,"neutrals":neutrals,"total":total,"over_rate":rate,"warning":warning}
    out["Slate Over Count"]=overs
    out["Slate Under Count"]=unders
    out["Slate Neutral Count"]=neutrals
    out["Slate Bias Warning"]=warning
    return out.sort_values(["Official Play Score","Hit Score","Edge"], ascending=[False,False,False])



# ============================================================
# STABLE SINGLE-PASS PROJECTION LOCK
# ============================================================
# The working Underdog parser above is intentionally untouched. This layer fixes
# projection inflation by making the calibrated v3.4.8 rebuild the only function
# allowed to change Projection. Context fields below are audit/display fields only.

APP_VERSION = "WNBA v5.1.0 - App128 Role Availability Challenger"
PROJECTION_ENGINE_VERSION = "V365_LEGACY_LOCKED_APP117"
PROJECTION_ENGINE_NOTE = "LEGACY LOCKED: season-isolated Bayesian baseline + bounded minutes/matchup. PTS V2 is a separate challenger and never overwrites legacy Projection."
PTS_V2_ENGINE_VERSION = "PTS_V2_TEAM_CONSTRAINED_CHALLENGER_V1"
PTS_V2_PROMOTE_TO_PRODUCTION = False


def _stable_context_value(br: Optional[pd.Series], row: pd.Series, names, default=np.nan):
    """Read a context value without allowing it to alter the final projection."""
    try:
        return _v344_value(br, row, list(names), default)
    except Exception:
        for name in names:
            try:
                value = safe_float(row.get(name), np.nan)
                if pd.notna(value):
                    return float(value)
            except Exception:
                pass
        return default


def _stable_weighted_stat(br: Optional[pd.Series], row: pd.Series, prefix: str) -> float:
    """Create an audit-only recent opportunity estimate from available data."""
    vals = []
    for col, weight in [
        (f"{prefix}_l5", 0.20),
        (f"{prefix}_l10", 0.35),
        (f"{prefix}_l20", 0.25),
        (f"{prefix}_avg", 0.20),
    ]:
        v = _stable_context_value(br, row, [col, col.upper(), col.lower()])
        if pd.notna(v):
            vals.append((float(v), weight))
    if not vals:
        return np.nan
    total_w = sum(w for _, w in vals)
    return sum(v*w for v, w in vals) / max(total_w, 1e-9)


def _stable_projected_fga(br: Optional[pd.Series], row: pd.Series, projected_minutes: float) -> float:
    """Project field-goal attempts from rolling game logs and projected minutes.

    Uses L5/L10/L20/season FGA rates when available. Older cached master files
    are also supported by converting season FGA totals back to per-game rates.
    This is an audit/display field only and does not change Projection or Lean.
    """
    fga_season = _stable_context_value(br, row, ["FGA_avg", "FGA_season", "Season FGA"])
    if pd.isna(fga_season):
        fga_total = _stable_context_value(br, row, ["FGA"])
        games = _stable_context_value(br, row, ["Games", "GP"], 0.0)
        if pd.notna(fga_total) and pd.notna(games) and float(games) > 0:
            fga_season = float(fga_total) / float(games)

    fga_l5 = _stable_context_value(br, row, ["FGA_l5", "FGA L5", "L5 FGA"])
    fga_l10 = _stable_context_value(br, row, ["FGA_l10", "FGA L10", "L10 FGA"])
    fga_l20 = _stable_context_value(br, row, ["FGA_l20", "FGA L20", "L20 FGA"])
    fga_values = [v for v in [fga_l5, fga_l10, fga_l20, fga_season] if pd.notna(v) and float(v) >= 0]
    if not fga_values:
        return np.nan
    fallback_fga = float(np.median(fga_values))
    fga_l5 = fallback_fga if pd.isna(fga_l5) else float(fga_l5)
    fga_l10 = fallback_fga if pd.isna(fga_l10) else float(fga_l10)
    fga_l20 = fallback_fga if pd.isna(fga_l20) else float(fga_l20)
    fga_season = fallback_fga if pd.isna(fga_season) else float(fga_season)
    fga_base = 0.25*fga_l5 + 0.35*fga_l10 + 0.25*fga_l20 + 0.15*fga_season

    min_avg = _stable_context_value(br, row, ["MIN_avg", "MIN", "Season Minutes"])
    min_l5 = _stable_context_value(br, row, ["MIN_l5", "Minutes L5", "L5 Minutes"])
    min_l10 = _stable_context_value(br, row, ["MIN_l10", "Minutes L10", "L10 Minutes"])
    min_l20 = _stable_context_value(br, row, ["MIN_l20", "Minutes L20", "L20 Minutes"])
    minute_values = [v for v in [min_l5, min_l10, min_l20, min_avg] if pd.notna(v) and float(v) > 0]
    if not minute_values or pd.isna(projected_minutes) or float(projected_minutes) <= 0:
        return float(np.clip(fga_base, 0.0, 35.0))
    fallback_min = float(np.median(minute_values))
    min_l5 = fallback_min if pd.isna(min_l5) or float(min_l5) <= 0 else float(min_l5)
    min_l10 = fallback_min if pd.isna(min_l10) or float(min_l10) <= 0 else float(min_l10)
    min_l20 = fallback_min if pd.isna(min_l20) or float(min_l20) <= 0 else float(min_l20)
    min_avg = fallback_min if pd.isna(min_avg) or float(min_avg) <= 0 else float(min_avg)
    minutes_base = 0.25*min_l5 + 0.35*min_l10 + 0.25*min_l20 + 0.15*min_avg
    if minutes_base <= 0:
        return float(np.clip(fga_base, 0.0, 35.0))
    projected = fga_base * (float(projected_minutes) / minutes_base)
    return float(np.clip(projected, 0.0, 35.0))


def _stable_attach_context_audit_only(board: pd.DataFrame, base: Optional[pd.DataFrame]) -> pd.DataFrame:
    """Populate useful context columns without modifying Projection, Edge, or side."""
    if board is None or board.empty:
        return board
    out = board.copy()
    lookup = _v344_player_lookup(base) if base is not None and not base.empty else pd.DataFrame()
    rows = []
    for _, rr in out.iterrows():
        row = rr.copy()
        key = normalize_name(row.get("Matched Player") or row.get("Player"))
        br = lookup.loc[key] if (not lookup.empty and key in lookup.index) else None
        market = str(row.get("Market", "PTS")).upper()

        l20 = _stable_context_value(br, row, [f"{market}_l20", "L20 Avg"])
        if pd.notna(l20):
            row["L20 Avg"] = round(float(l20), 2)

        minutes = safe_float(row.get("MIN Proj"), safe_float(br.get("MinutesProjectionBase"), np.nan) if br is not None else np.nan)
        fga = _stable_projected_fga(br, row, minutes)
        three_pa = _stable_weighted_stat(br, row, "FG3A")
        fta = _stable_weighted_stat(br, row, "FTA")
        if pd.isna(fga):
            fga = safe_float(row.get("Projected FGA"), np.nan)
        if pd.notna(fga):
            row["Projected FGA"] = round(float(fga), 2)
            row["Projected FGA 2.0"] = round(float(fga), 2)
            row["FGA Projection Source"] = "L5/L10/L20/season FGA adjusted to projected minutes"
        if pd.notna(three_pa):
            row["Projected 3PA 2.0"] = round(float(three_pa), 2)
        if pd.notna(fta):
            row["Projected FTA 2.0"] = round(float(fta), 2)

        min_conf = safe_float(row.get("Minutes Confidence"), safe_float(row.get("Final Projection Confidence"), np.nan))
        row["Minutes 2.0 Projection"] = round(minutes, 2) if pd.notna(minutes) else np.nan
        row["Minutes 2.0 Confidence"] = round(min_conf, 1) if pd.notna(min_conf) else np.nan

        usg_l5 = _stable_context_value(br, row, ["USG_l5", "USG%_L5", "Usage L5"])
        usg_l10 = _stable_context_value(br, row, ["USG_l10", "USG%_L10", "Usage L10"])
        usage_trend = np.nan
        if pd.notna(usg_l5) and pd.notna(usg_l10) and abs(float(usg_l10)) > 1e-9:
            usage_trend = float(np.clip((float(usg_l5) / float(usg_l10)) - 1.0, -0.30, 0.30))
        row["Usage Trend"] = round(usage_trend, 4) if pd.notna(usage_trend) else np.nan
        row["Live Usage Factor"] = 1.0

        opp_pace = safe_float(row.get("Opponent Pace"), np.nan)
        game_pace = safe_float(row.get("Projected Pace"), safe_float(row.get("Game Pace Projection"), np.nan))
        poss_vals = [x for x in [opp_pace, game_pace] if pd.notna(x)]
        projected_poss = float(np.mean(poss_vals)) if poss_vals else np.nan
        row["Projected Possessions"] = round(projected_poss, 2) if pd.notna(projected_poss) else np.nan
        row["Possession Factor"] = 1.0
        row["Shot Volume Factor"] = 1.0
        row["Rebound Opportunity Factor"] = 1.0

        blowout = safe_float(row.get("Blowout Risk %"), safe_float(row.get("Blowout Risk"), np.nan))
        if pd.notna(blowout):
            row["Blowout Risk %"] = round(float(blowout), 1)
        volatility = safe_float(row.get("Volatility Score"), np.nan)
        if pd.isna(volatility):
            sd = safe_float(row.get("Simulation SD"), np.nan)
            if pd.notna(sd):
                volatility = float(np.clip(45 + sd*6, 35, 95))
        if pd.notna(volatility):
            row["Volatility Score"] = round(float(volatility), 1)
            row["Volatility Tier 2.0"] = "HIGH" if volatility >= 78 else "LOW" if volatility <= 55 else "MEDIUM"

        proj = safe_float(row.get("Projection"), np.nan)
        line = safe_float(row.get("Line"), np.nan)
        disagreement = abs(proj-line) if pd.notna(proj) and pd.notna(line) else np.nan
        row["Market Disagreement"] = round(disagreement, 2) if pd.notna(disagreement) else np.nan
        row["Market Intelligence Flag"] = (
            "LARGE MODEL/MARKET DISAGREEMENT"
            if pd.notna(disagreement) and disagreement >= {"PTS": 5.0, "REB": 2.2, "AST": 2.0, "PRA": 7.5}.get(market, 4.0)
            else "NORMAL"
        )
        row["Context Total Multiplier"] = 1.0
        row["Context Base Projection"] = round(proj, 2) if pd.notna(proj) else np.nan
        row["Context Explain"] = "Audit only: minutes, usage, possessions, shot volume, rebound opportunity, blowout, volatility, and market disagreement are displayed but are not stacked onto Projection."
        row["Projection Engine Version"] = PROJECTION_ENGINE_VERSION
        row["Projection Audit"] = PROJECTION_ENGINE_NOTE
        rows.append(row)
    return pd.DataFrame(rows)


def _strong_text_blob(row: pd.Series, names: List[str]) -> str:
    return " ".join(str(row.get(name, "") or "") for name in names).upper()


def _strong_availability_risk(row: pd.Series) -> Tuple[bool, str]:
    txt = _strong_text_blob(row, [
        "Injury Status", "Availability", "Lineup Status", "Starter Status",
        "Role", "Injury Context Note", "Projected Rotation Note", "Bench Rotation Note"
    ])
    bad = ["OUT", "INACTIVE", "DOUBTFUL", "SUSPENDED", "MINUTES LIMIT", "LIMITED MINUTES", "GTD", "GAME TIME DECISION"]
    caution = ["QUESTIONABLE", "PROBABLE", "RETURNING", "REST", "ILLNESS"]
    if any(tag in txt for tag in bad):
        return True, "availability/minutes risk"
    if any(tag in txt for tag in caution):
        return True, "availability needs confirmation"
    return False, "availability clean"


def _strong_recent_support(row: pd.Series, line: float, lean: str) -> Tuple[int, str]:
    if pd.isna(line) or lean not in {"OVER", "UNDER"}:
        return 0, "no side support"
    labels = [("L5", "L5 Avg"), ("L10", "L10 Avg"), ("L20", "L20 Avg"), ("Season", "Season Avg")]
    hits = []
    for label, col in labels:
        value = safe_float(row.get(col), np.nan)
        if pd.notna(value):
            agrees = (value > line) == (lean == "OVER")
            hits.append((label, agrees))
    votes = sum(1 for _, agrees in hits if agrees)
    note = f"{votes}/{len(hits)} recent/season windows support {lean}" if hits else "recent/season windows unavailable"
    return votes, note


def _window_hit_rate(values: List[float], line: float, lean: str, n: int) -> Tuple[int, int, float]:
    vals = [float(v) for v in values[-n:] if pd.notna(v)]
    if not vals or pd.isna(line) or lean not in {"OVER", "UNDER"}:
        return 0, 0, np.nan
    hits = sum(1 for v in vals if (v > line) == (lean == "OVER"))
    return hits, len(vals), hits / max(1, len(vals)) * 100.0


def _player_log_cache_signature() -> str:
    """Invalidate the prepared game-log lookup when the persisted CSV changes."""
    path = CACHE_FILES.get("player_game_logs")
    try:
        stat = Path(path).stat()
        return f"{stat.st_mtime_ns}:{stat.st_size}"
    except Exception:
        return "missing"


def _prepared_player_market_logs(signature: str) -> pd.DataFrame:
    """Prepare dated logs once; individual player histories are cached lazily."""
    try:
        logs = load_dataset("player_game_logs")
    except Exception:
        logs = pd.DataFrame()
    if logs is None or logs.empty:
        return pd.DataFrame()
    d = standardize_player_logs(logs)
    if d is None or d.empty:
        return pd.DataFrame()
    d = d.copy()
    d["OpponentKey"] = d.get("Opponent", pd.Series("", index=d.index)).map(_team_key_for_matchup)
    if "GameDate" in d.columns:
        d = d.sort_values("GameDate", kind="stable", na_position="first")
    keep = [column for column in ["NameKey", "OpponentKey", "GameDate"] + MARKETS if column in d.columns]
    return d[keep].reset_index(drop=True)


_RUNTIME_PLAYER_LOG_SIGNATURE = ""
_RUNTIME_PLAYER_LOGS = pd.DataFrame()
_RUNTIME_PLAYER_LOG_LOOKUP: Dict[Tuple[str, str, str], List[float]] = {}


def _player_market_log_values(player: str, market: str, opponent: str = "") -> List[float]:
    global _RUNTIME_PLAYER_LOG_SIGNATURE, _RUNTIME_PLAYER_LOGS, _RUNTIME_PLAYER_LOG_LOOKUP
    key = normalize_name(player)
    if not key:
        return []
    opponent_key = _team_key_for_matchup(opponent) if opponent else ""
    signature = _player_log_cache_signature()
    if signature != _RUNTIME_PLAYER_LOG_SIGNATURE:
        _RUNTIME_PLAYER_LOGS = _prepared_player_market_logs(signature)
        _RUNTIME_PLAYER_LOG_LOOKUP = {}
        _RUNTIME_PLAYER_LOG_SIGNATURE = signature
    cache_key = (key, str(market).upper(), opponent_key)
    if cache_key not in _RUNTIME_PLAYER_LOG_LOOKUP:
        if _RUNTIME_PLAYER_LOGS.empty or cache_key[1] not in _RUNTIME_PLAYER_LOGS.columns:
            _RUNTIME_PLAYER_LOG_LOOKUP[cache_key] = []
        else:
            player_rows = _RUNTIME_PLAYER_LOGS[_RUNTIME_PLAYER_LOGS["NameKey"].astype(str).eq(key)]
            if opponent_key:
                player_rows = player_rows[player_rows["OpponentKey"].astype(str).eq(opponent_key)]
            _RUNTIME_PLAYER_LOG_LOOKUP[cache_key] = (
                pd.to_numeric(player_rows[cache_key[1]], errors="coerce").dropna().astype(float).tolist()
            )
    return list(_RUNTIME_PLAYER_LOG_LOOKUP[cache_key])


def _hit_rate_context(row: pd.Series, market: str, line: float, lean: str) -> Tuple[int, str]:
    values = _player_market_log_values(row.get("Player"), market)
    h2h_values = _player_market_log_values(row.get("Player"), market, row.get("Opponent"))
    pieces = []
    support_points = 0
    for n in [3, 5, 10]:
        hits, total, pct = _window_hit_rate(values, line, lean, n)
        if total:
            pieces.append(f"L{n} {hits}/{total} ({pct:.0f}%)")
            if pct >= 60:
                support_points += 1
    hh, ht, hpct = _window_hit_rate(h2h_values, line, lean, 10)
    if ht:
        pieces.append(f"H2H {hh}/{ht} ({hpct:.0f}%)")
        if hpct >= 60 and ht >= 2:
            support_points += 1
    return support_points, " · ".join(pieces) if pieces else "hit-rate history unavailable"


def _veteran_capability_context(row: pd.Series, br: Optional[pd.Series], market: str, lean: str, line: float) -> Tuple[int, str]:
    if br is None:
        return 0, "baseline missing"
    games = safe_float(br.get("Games"), safe_float(br.get("GP"), 0))
    min_avg = safe_float(br.get("MIN_avg"), np.nan)
    starter_rate = safe_float(br.get("StarterRate"), np.nan)
    usage = safe_float(br.get("UsageProxy"), safe_float(br.get("USG%"), np.nan))
    season = safe_float(br.get(f"{market}_avg"), np.nan)
    l10 = safe_float(br.get(f"{market}_l10"), np.nan)
    cap = 0
    tags = []
    if games >= 55:
        cap += 1; tags.append("veteran sample")
    elif games >= 25:
        tags.append("regular sample")
    if pd.notna(min_avg) and min_avg >= 26:
        cap += 1; tags.append(f"{min_avg:.1f} min")
    if pd.notna(starter_rate) and starter_rate >= 0.55:
        cap += 1; tags.append("starter role")
    if pd.notna(usage) and usage >= 12 and market in {"PTS", "PRA"}:
        cap += 1; tags.append("usage capable")
    if pd.notna(season) and pd.notna(line):
        if (season > line) == (lean == "OVER"):
            cap += 1; tags.append("season supports")
        elif pd.notna(l10) and (l10 > line) == (lean == "OVER"):
            cap += 1; tags.append("recent supports")
    return cap, ", ".join(tags[:5]) if tags else "capability neutral"


def _strong_line_context(row: pd.Series, line: float, lean: str) -> Tuple[bool, str]:
    """Use opening/consensus lines when present; neutral when absent."""
    if lean not in {"OVER", "UNDER"} or pd.isna(line):
        return False, "no line context"
    opening = safe_float(row.get("Opening Line"), safe_float(row.get("Open Line"), np.nan))
    consensus = safe_float(row.get("Consensus Line"), safe_float(row.get("Market Consensus"), np.nan))
    notes = []
    supported = True
    if pd.notna(opening):
        move = line - opening
        if lean == "OVER" and move < -0.5:
            supported = False
        if lean == "UNDER" and move > 0.5:
            supported = False
        notes.append(f"open {opening:.1f} -> {line:.1f}")
    if pd.notna(consensus):
        if lean == "OVER" and consensus < line - 0.5:
            supported = False
        if lean == "UNDER" and consensus > line + 0.5:
            supported = False
        notes.append(f"consensus {consensus:.1f}")
    if not notes:
        return True, "line movement/consensus unavailable"
    return supported, "; ".join(notes)


def _strong_play_gate(row: pd.Series, market: str, lean: str, edge: float, sidep: float, confidence: float, votes: int) -> Dict[str, Any]:
    edge_abs = abs(edge) if pd.notna(edge) else np.nan
    thresholds = {
        "PTS": {"edge": 1.75, "prob": 61.0, "conf": 76.0, "minutes": 72.0, "votes": 4},
        "REB": {"edge": 1.00, "prob": 61.0, "conf": 76.0, "minutes": 72.0, "votes": 4},
        "AST": {"edge": 0.85, "prob": 61.0, "conf": 76.0, "minutes": 72.0, "votes": 4},
        "PRA": {"edge": 2.50, "prob": 61.0, "conf": 76.0, "minutes": 72.0, "votes": 4},
    }.get(market, {"edge": 1.25, "prob": 61.0, "conf": 76.0, "minutes": 72.0, "votes": 4})
    integrity = str(row.get("Data Integrity", "LIMITED")).upper()
    sanity = str(row.get("Projection Sanity", "PASS")).upper()
    minutes_conf = safe_float(row.get("Minutes Confidence"), safe_float(row.get("Minutes 2.0 Confidence"), confidence))
    opp_ok = bool(str(row.get("Opponent", "")).strip()) and pd.notna(safe_float(row.get("Opponent Pace"), np.nan)) and pd.notna(safe_float(row.get("Opponent DRtg"), np.nan))
    avail_risk, avail_note = _strong_availability_risk(row)
    line_ok, line_note = _strong_line_context(row, safe_float(row.get("Line"), np.nan), lean)
    freshness = str(row.get("Freshness Status", "UNKNOWN")).upper()
    line_snapshots = safe_float(row.get("Line Snapshot Count"), np.nan)
    lineup_confirmed = bool(row.get("Lineup Confirmed", False))
    late_scratch_risk = bool(row.get("Late Scratch Risk", False))
    minutes_to_tip = safe_float(row.get("Minutes Until Tip"), np.nan)
    opening_line = safe_float(row.get("Opening Line"), np.nan)

    missing = []
    if lean not in {"OVER", "UNDER"}: missing.append("no clear OVER/UNDER lean")
    if integrity != "VERIFIED": missing.append("data integrity not verified")
    if sanity not in {"PASS", "OK", "VERIFIED"}: missing.append("projection sanity not clean")
    if pd.isna(edge_abs) or edge_abs < thresholds["edge"]: missing.append(f"edge below {thresholds['edge']:.1f}")
    if sidep < thresholds["prob"]: missing.append(f"probability below {thresholds['prob']:.0f}%")
    if confidence < thresholds["conf"]: missing.append(f"projection confidence below {thresholds['conf']:.0f}%")
    if minutes_conf < thresholds["minutes"]: missing.append(f"minutes confidence below {thresholds['minutes']:.0f}%")
    if votes < thresholds["votes"]: missing.append("recent/season support too weak")
    if not opp_ok: missing.append("opponent pace/DRtg missing")
    if avail_risk: missing.append(avail_note)
    if not line_ok: missing.append("line movement/consensus against side")
    if freshness == "STALE": missing.append("data or line feed stale")
    if pd.isna(line_snapshots) or line_snapshots < 1: missing.append("line snapshot history missing")
    if pd.isna(opening_line): missing.append("opening line unavailable")
    if late_scratch_risk: missing.append("late scratch/start check required")
    if pd.notna(minutes_to_tip) and minutes_to_tip <= 120 and not lineup_confirmed:
        missing.append("starter/lineup not confirmed near tip")

    edge_score = 0.0 if pd.isna(edge_abs) else min(100.0, edge_abs / thresholds["edge"] * 100.0)
    strong_score = float(np.clip(
        0.34*sidep + 0.22*confidence + 0.16*minutes_conf + 0.14*edge_score + 0.14*min(100.0, votes/4.0*100.0),
        0, 100
    ))
    label = "LONG STRONG " + lean if not missing else "TRACK"
    reasons = [
        f"{sidep:.1f}% side probability",
        f"{edge_abs:.2f} edge" if pd.notna(edge_abs) else "edge unavailable",
        f"{votes} evidence support",
        f"{confidence:.1f}% projection confidence",
        f"{minutes_conf:.1f}% minutes confidence",
        line_note,
        f"freshness {freshness}",
        "lineup confirmed" if lineup_confirmed else "lineup not confirmed",
    ]
    return {
        "passed": not missing,
        "label": label,
        "score": round(strong_score, 1),
        "reasons": " · ".join(reasons),
        "missing": " · ".join(dict.fromkeys(missing)),
    }


def _stable_recalculate_side_fields(board: pd.DataFrame, base: Optional[pd.DataFrame] = None) -> pd.DataFrame:
    """Keep projection fixed and make Edge/Lean/probability/Official internally consistent."""
    if board is None or board.empty:
        return board
    out = board.copy()
    lookup = _v344_player_lookup(base) if base is not None and not base.empty else pd.DataFrame()
    repaired = []
    for _, rr in out.iterrows():
        row = rr.copy()
        market = str(row.get("Market", "PTS")).upper()
        proj = safe_float(row.get("Projection"), np.nan)
        line = safe_float(row.get("Line"), np.nan)
        edge = proj-line if pd.notna(proj) and pd.notna(line) else np.nan
        key = normalize_name(row.get("Matched Player") or row.get("Player"))
        br = lookup.loc[key] if (not lookup.empty and key in lookup.index) else None
        confidence = safe_float(row.get("Final Projection Confidence"), 70.0)
        sd = safe_float(row.get("Simulation SD"), np.nan)
        if pd.isna(sd) and pd.notna(proj):
            try:
                sd = _v344_sd(br, market, proj, confidence)
            except Exception:
                sd = {"PTS": 4.8, "REB": 2.3, "AST": 2.1, "PRA": 6.8}.get(market, 4.0)
        overp = _v344_probability(line, proj, sd) if pd.notna(line) and pd.notna(proj) else np.nan
        underp = 100.0-overp if pd.notna(overp) else np.nan

        neutral_edge = {"PTS":0.75,"REB":0.40,"AST":0.40,"PRA":1.25}.get(market,0.75)
        min_prob = 54.5
        if pd.isna(edge):
            lean = "PASS"
        elif edge >= neutral_edge and pd.notna(overp) and overp >= min_prob:
            lean = "OVER"
        elif edge <= -neutral_edge and pd.notna(underp) and underp >= min_prob:
            lean = "UNDER"
        else:
            lean = "NEUTRAL"
        sidep = overp if lean == "OVER" else underp if lean == "UNDER" else max(overp, underp) if pd.notna(overp) else 0.0

        vals = []
        for c in ["L5 Avg", "L10 Avg", "L20 Avg", "Season Avg"]:
            v = safe_float(row.get(c), np.nan)
            if pd.notna(v): vals.append(v)
        votes, recent_note = _strong_recent_support(row, line, lean)
        hit_support, hit_note = _hit_rate_context(row, market, line, lean)
        vet_support, vet_note = _veteran_capability_context(row, br, market, lean, line)
        game_ctx = _wnba_game_script_context(row)
        game_support = int(game_ctx.get("support", 0))
        row["WNBA ML Game Script"] = game_ctx.get("note", "WNBA ML game script unavailable")
        row["WNBA ML Game Script Factor"] = round(safe_float(game_ctx.get("factor"), 1.0), 4)
        row["Projected Team Score ML"] = round(safe_float(game_ctx.get("team_score"), np.nan), 1) if game_ctx.get("ok") else np.nan
        row["Projected Opp Score ML"] = round(safe_float(game_ctx.get("opp_score"), np.nan), 1) if game_ctx.get("ok") else np.nan
        row["Projected Game Total ML"] = round(safe_float(game_ctx.get("total"), np.nan), 1) if game_ctx.get("ok") else np.nan
        row["Projected Spread ML"] = round(safe_float(game_ctx.get("spread"), np.nan), 1) if game_ctx.get("ok") else np.nan
        row["Team Win Probability ML"] = round(safe_float(game_ctx.get("win_prob"), np.nan), 1) if game_ctx.get("ok") else np.nan
        row["Game Pace ML"] = round(safe_float(game_ctx.get("pace"), np.nan), 1) if game_ctx.get("ok") else np.nan
        row["Blowout Risk ML"] = round(safe_float(game_ctx.get("blowout_risk"), np.nan), 1) if game_ctx.get("ok") else np.nan

        integrity = str(row.get("Data Integrity", "LIMITED")).upper()
        official_edge = {"PTS":2.00,"REB":1.20,"AST":1.00,"PRA":3.00}.get(market,1.50)
        official_prob = {"PTS":62.0,"REB":62.0,"AST":62.0,"PRA":62.0}.get(market,62.0)
        reasons = []
        if lean not in {"OVER", "UNDER"}: reasons.append("inside neutral/no-play zone")
        if integrity != "VERIFIED": reasons.append("data/opponent context not verified")
        if pd.isna(edge) or abs(edge) < official_edge: reasons.append("edge below official threshold")
        if sidep < official_prob: reasons.append("probability below official threshold")
        if votes < 2: reasons.append("recent/season support is weak")
        if confidence < 80: reasons.append("projection confidence below 80%")
        evidence_votes = votes + hit_support + min(2, vet_support) + game_support
        row["Hit Rate Context"] = hit_note
        row["Veteran Capability"] = vet_note
        row["Evidence Support Score"] = evidence_votes
        strong_gate = _strong_play_gate(row, market, lean, edge, sidep, confidence, evidence_votes)
        if strong_gate["missing"]:
            reasons.extend(strong_gate["missing"].split(" · "))
        lean_edge_req = {"PTS":1.15,"REB":0.70,"AST":0.60,"PRA":1.80}.get(market,1.0)
        lean_ok = (
            lean in {"OVER", "UNDER"}
            and pd.notna(edge)
            and abs(edge) >= lean_edge_req
            and sidep >= 57.0
            and confidence >= 68.0
            and evidence_votes >= 3
            and integrity == "VERIFIED"
        )
        strong_ok = lean_ok and abs(edge) >= {"PTS":1.60,"REB":0.95,"AST":0.85,"PRA":2.40}.get(market,1.25) and sidep >= 60.0 and evidence_votes >= 4
        official = strong_gate["label"] if strong_gate["passed"] else (f"STRONG {lean}" if strong_ok else f"LEAN {lean}" if lean_ok else "PASS")

        # Preserve the calibrated score formula but force it to use the selected side.
        edge_scale = {"PTS":6.0,"REB":11.0,"AST":11.0,"PRA":3.8}.get(market,6.0)
        edge_score = float(np.clip(50 + abs(edge if pd.notna(edge) else 0)*edge_scale, 0, 100))
        script_score = float(np.clip(50 + game_support * 14, 25, 78))
        hit_score = float(np.clip(0.42*sidep + 0.22*confidence + 0.15*edge_score + 0.13*(40+votes*13) + 0.08*script_score, 0, 100))

        row["Edge"] = round(edge, 2) if pd.notna(edge) else np.nan
        row["Lean"] = lean
        row["Over %"] = round(overp, 1) if pd.notna(overp) else np.nan
        row["Under %"] = round(underp, 1) if pd.notna(underp) else np.nan
        row["Simulation SD"] = round(sd, 2) if pd.notna(sd) else np.nan
        row["Hit Score"] = round(hit_score, 1)
        row["Official Play Score"] = round(strong_gate["score"] if strong_gate["passed"] else hit_score, 1)
        row["Official"] = official
        row["Strong Play"] = official
        row["Strong Play Score"] = strong_gate["score"]
        row["Strong Play Reasons"] = strong_gate["reasons"]
        row["Strong Play Missing"] = strong_gate["missing"]
        row["Recent Support"] = f"{recent_note} | {hit_note} | ML script: {game_ctx.get('note', 'unavailable')}"
        row["Tier"] = "LONG" if official.startswith("LONG STRONG") else "STRONG" if official.startswith("STRONG") else "LEAN" if official.startswith("LEAN") else "TRACK"
        row["PASS Reason"] = " · ".join(dict.fromkeys(reasons))
        repaired.append(row)

    out = pd.DataFrame(repaired)
    actionable = out[out["Lean"].isin(["OVER", "UNDER"])]
    overs = int((actionable["Lean"] == "OVER").sum())
    unders = int((actionable["Lean"] == "UNDER").sum())
    neutrals = int((out["Lean"] == "NEUTRAL").sum())
    total = len(actionable)
    over_rate = overs/max(1,total)
    warning = "BALANCED"
    if total >= 8 and over_rate >= 0.75:
        warning = f"OVER-SKEW WARNING: {overs}/{total} actionable projections. Review the stable baseline inputs; no sides were force-balanced."
    elif total >= 8 and over_rate <= 0.25:
        warning = f"UNDER-SKEW WARNING: {unders}/{total} actionable projections. Review the stable baseline inputs; no sides were force-balanced."
    st.session_state["wnba_slate_bias_summary"] = {"overs":overs,"unders":unders,"neutrals":neutrals,"total":total,"over_rate":over_rate,"warning":warning}
    out["Slate Over Count"] = overs
    out["Slate Under Count"] = unders
    out["Slate Neutral Count"] = neutrals
    out["Slate Bias Warning"] = warning
    return out.sort_values(["Official Play Score", "Hit Score", "Edge"], ascending=[False, False, False])


def _stable_repair_projection_board(board: pd.DataFrame, base: Optional[pd.DataFrame]) -> pd.DataFrame:
    """Rebuild an old/inflated cached board using the exact same lines and the stable v3.4.8 model."""
    if board is None or board.empty:
        return board
    rebuilt = _v344_rebuild_board(board.copy(), base)
    rebuilt = _stable_attach_context_audit_only(rebuilt, base)
    rebuilt = _stable_recalculate_side_fields(rebuilt, base)
    rebuilt["Projection Engine Version"] = PROJECTION_ENGINE_VERSION
    return rebuilt


def _historical_make_projection_board_8(lines, logs, base, mode: Optional[str] = None):
    """Single-pass projection builder. The Underdog line pull remains unchanged."""
    board = _make_projection_board_v344_input(lines, logs, base, mode)
    board = _v344_rebuild_board(board, base)
    board = _stable_attach_context_audit_only(board, base)
    board = _stable_recalculate_side_fields(board, base)
    if board is not None and not board.empty:
        board["Projection Engine Version"] = PROJECTION_ENGINE_VERSION
        save_dataset("projection_board", board)
    return board


def automatic_hhs_refresh(force: bool = False, blocking: bool = False) -> pd.DataFrame:
    """Check the authorized HHS feed on every run without blocking UI reruns.

    Ordinary Streamlit reruns schedule a due refresh in a daemon thread. The
    explicit full-board refresh uses ``blocking=True`` so projections consume
    the newest completely validated HHS cache batch.
    """
    repository = HHSRepository()
    try:
        if force or blocking:
            report = repository.refresh_if_due(force=force)
        else:
            report = repository.refresh_state()
            status = str(report.iloc[0].get("Status", "")) if not report.empty else ""
            if status == "DUE":
                def _refresh_in_background() -> None:
                    try:
                        repository.refresh_if_due(force=False)
                    except Exception:
                        logging.getLogger("wnba.hhs").exception(
                            "Background HHS refresh failed; last-good cache preserved"
                        )

                threading.Thread(
                    target=_refresh_in_background,
                    name="wnba-hhs-refresh",
                    daemon=True,
                ).start()
                report = pd.DataFrame([{
                    "Dataset": "all",
                    "Status": "REFRESH_SCHEDULED",
                    "Rows": int(repository.coverage()["rows_loaded"]),
                    "Message": "authorized HHS refresh is running in the background; last-good cache remains active",
                }])
    except Exception as exc:
        report = pd.DataFrame([{
            "Dataset": "all", "Status": "FAILED_SAFE", "Rows": 0,
            "Message": f"HHS refresh failed; last-good cache/legacy model preserved: {str(exc)[:220]}",
        }])
    try:
        st.session_state["wnba_hhs_auto_refresh_report"] = report.to_dict("records")
    except Exception:
        pass
    return report


def refresh_cached_hhs_comparison_if_changed() -> str:
    """Reattach challenger columns only when the validated HHS cache changed."""
    try:
        board = load_dataset("projection_board")
        if board is None or board.empty:
            return "NO_BOARD"
        parser_versions = set(
            board.get("LineParserVersion", pd.Series(dtype=str)).dropna().astype(str).unique().tolist()
        )
        if LINE_PARSER_VERSION not in parser_versions:
            return "OLD_BOARD"
        repository = HHSRepository()
        signature = repository.cache_signature()
        board_signatures = set(
            board.get("HHS Data Signature", pd.Series(dtype=str)).dropna().astype(str).unique().tolist()
        )
        if board_signatures == {signature}:
            return "CURRENT"
        legacy_projection = pd.to_numeric(board.get("Projection"), errors="coerce").copy()
        refreshed = attach_model_comparison(board, repository=repository, simulations=10_000)
        if not np.allclose(
            pd.to_numeric(refreshed.get("Projection"), errors="coerce"),
            legacy_projection,
            equal_nan=True,
        ):
            raise RuntimeError("HHS cache update attempted to change the legacy Projection column")
        save_dataset("projection_board", refreshed)
        return "UPDATED"
    except Exception as exc:
        try:
            st.session_state["wnba_hhs_board_refresh_error"] = str(exc)[:240]
        except Exception:
            pass
        return "FAILED_SAFE"


def render_hhs_model_tab() -> None:
    """Authorized HHS import, diagnostics, and legacy/challenger comparison."""
    repository = HHSRepository()
    coverage = repository.coverage()
    st.subheader("Her Hoop Stats / Model Comparison")
    st.caption(
        "Final Resolved is the active production authority. Legacy, HHS, Hybrid, and raw Elite component outputs remain visible for audit/comparison; "
        "the app never crawls subscriber pages or silently promotes an unvalidated external blend."
    )
    c1, c2, c3, c4 = st.columns(4)
    c1.metric("HHS datasets", f"{coverage['datasets_available']}/{coverage['datasets_expected']}")
    c2.metric("HHS rows", f"{coverage['rows_loaded']:,}")
    c3.metric("Last HHS refresh", coverage["last_refresh"] or "not loaded")
    c4.metric("Active model", "FINAL RESOLVED")
    auto_report = pd.DataFrame(st.session_state.get("wnba_hhs_auto_refresh_report", []))
    if not auto_report.empty:
        auto_status = ", ".join(sorted(auto_report.get("Status", pd.Series(dtype=str)).dropna().astype(str).unique().tolist()))
        st.caption(f"Automatic authorized-feed check: {auto_status or 'unknown'}. Refreshes are TTL-cached and failures preserve the last-good HHS data.")

    data_tab, compare_tab, evaluation_tab, diagnostics_tab = st.tabs(
        ["HHS Data", "Model Compare", "Evaluation", "Diagnostics"]
    )
    with data_tab:
        st.info(
            "Import an HHS CSV/Parquet/XLSX/JSON export that you are authorized to use. "
            "Missing or rejected data leaves the last good cache and legacy app untouched."
        )
        dataset = st.selectbox(
            "HHS dataset type",
            list(DATASET_KEYS),
            format_func=lambda value: value.replace("hhs_", "").replace("_", " ").title(),
            key="hhs_dataset_type",
        )
        upload = st.file_uploader(
            "Authorized HHS export",
            type=["csv", "parquet", "xlsx", "xls", "json"],
            key="hhs_authorized_upload",
        )
        if st.button("Import validated HHS export", disabled=upload is None, use_container_width=True):
            report = repository.import_bytes(dataset, upload.getvalue(), upload.name)
            st.dataframe(pd.DataFrame([report.as_dict()]), use_container_width=True, hide_index=True)
            if report.ok:
                st.success(f"Imported {report.rows_valid:,} validated rows into {dataset}.")
                st.cache_data.clear()
            else:
                st.error("Import rejected. The last successful HHS cache was preserved.")
        configured = bool(repository.config.structured_base_url)
        st.caption(
            "Optional structured endpoint: set HHS_STRUCTURED_DATA_BASE_URL to an authorized "
            "manifest folder and HHS_API_TOKEN when required. Direct HHS HTML crawling is blocked."
        )
        if st.button("Force refresh authorized structured endpoint", disabled=not configured, use_container_width=True):
            with st.spinner("Refreshing authorized structured HHS exports..."):
                refresh_report = automatic_hhs_refresh(force=True)
            st.dataframe(refresh_report, use_container_width=True, hide_index=True)
            st.cache_data.clear()
        cache_zip = repository.export_cache_zip()
        if cache_zip:
            st.download_button(
                "Download HHS cache backup",
                cache_zip,
                "wnba_hhs_cache_backup.zip",
                "application/zip",
                use_container_width=True,
            )

    with compare_tab:
        board = load_dataset("projection_board")
        if board is None or board.empty:
            st.info("No projection board is cached yet.")
        else:
            if "Model Comparison Version" not in board.columns:
                try:
                    board = attach_model_comparison(board, repository=repository, simulations=10_000)
                except Exception as exc:
                    st.error(f"HHS comparison unavailable; legacy board remains active: {exc}")
            columns = [
                "Player", "Team", "Opponent", "Market", "Line", "Active Model",
                "Legacy Projection", "HHS Projection", "HHS P50", "Hybrid Projection",
                "HHS Over %", "HHS Under %", "HHS Direction", "HHS Confidence Tier",
                "HHS Data Quality", "HHS Projected Minutes", "HHS Minutes Confidence",
                "HHS Matchup Score", "HHS Distribution Conflict", "Model Agreement Count",
                "HHS Model Status", "Hybrid Status",
            ]
            display = board[[column for column in columns if column in board.columns]].copy()
            st.dataframe(display, use_container_width=True, hide_index=True)
            st.download_button(
                "Download Legacy vs HHS vs Hybrid CSV",
                board.to_csv(index=False),
                "wnba_legacy_hhs_hybrid_comparison.csv",
                "text/csv",
                use_container_width=True,
            )

    with evaluation_tab:
        graded = pd.DataFrame(load_json(LEARNING_LOG, []))
        evaluation_rows = model_evaluation_rows(graded)
        if evaluation_rows.empty:
            st.info(
                "No same-slate graded HHS snapshots are available yet. Save boards before games, "
                "grade the exact snapshots, and return here to compare models."
            )
        else:
            summary = summarize_hhs_models(evaluation_rows)
            st.markdown("#### Same-slate model metrics")
            st.dataframe(summary, use_container_width=True, hide_index=True)
            calibration = hhs_calibration_table(evaluation_rows)
            st.markdown("#### Probability calibration")
            st.dataframe(calibration, use_container_width=True, hide_index=True)
            recommendations = validated_hybrid_recommendations(evaluation_rows)
            st.markdown("#### Hybrid holdout validation")
            st.dataframe(recommendations, use_container_width=True, hide_index=True)
            st.caption(
                "Recommendations use a chronological train/holdout split and are not promoted automatically."
            )
            misses = hhs_diagnose_misses(evaluation_rows)
            with st.expander("Miss diagnosis queue", expanded=False):
                st.dataframe(misses, use_container_width=True, hide_index=True)
            st.download_button(
                "Download model evaluation rows",
                evaluation_rows.to_csv(index=False),
                "wnba_model_evaluation_rows.csv",
                "text/csv",
                use_container_width=True,
            )

    with diagnostics_tab:
        st.markdown("#### HHS cache diagnostics")
        st.dataframe(repository.diagnostics(), use_container_width=True, hide_index=True)
        match_path = repository.config.root / "hhs_player_match_diagnostics.csv"
        if match_path.exists():
            st.markdown("#### Player identity diagnostics")
            st.dataframe(pd.read_csv(match_path, low_memory=False), use_container_width=True, hide_index=True)
        store = ProjectionSnapshotStore(LOCAL_DIR / "wnba_projection_history.sqlite3")
        st.markdown("#### Immutable projection batches")
        st.dataframe(store.list_batches(), use_container_width=True, hide_index=True)
        if coverage["last_error"]:
            st.warning(f"Last HHS error: {coverage['last_error']}")


def _stable_load_or_repair_cached_board(mode: str, base: Optional[pd.DataFrame]) -> tuple:
    board, label = _load_last_good_projection_board(mode)
    if board is None or board.empty:
        return pd.DataFrame(), label
    versions = set(board.get("Projection Engine Version", pd.Series(dtype=str)).dropna().astype(str).unique().tolist())
    if PROJECTION_ENGINE_VERSION not in versions:
        try:
            board = _stable_repair_projection_board(board, base)
            board.to_csv(CACHE_FILES["projection_board"], index=False)
            label = f"repaired {label}"
        except Exception as exc:
            st.session_state["wnba_projection_cache_repair_error"] = str(exc)[:220]
    elif "Model Comparison Version" not in board.columns:
        try:
            board = attach_model_comparison(board, repository=HHSRepository(), simulations=10_000)
            board.to_csv(CACHE_FILES["projection_board"], index=False)
            label = f"HHS-enriched {label}"
        except Exception as exc:
            st.session_state["wnba_hhs_cache_enrich_error"] = str(exc)[:220]
    return board, label


def _app120_refresh_core_projection_data(mode: str) -> Tuple[pd.DataFrame, pd.DataFrame, Dict[str, Any]]:
    """Refresh current-season inputs on an explicit user refresh.

    Existing caches are preserved when the remote source is unavailable.
    Heavy shot/lineup downloads remain in Data Manager.
    """
    target = slate_target_date(mode) or app_today()
    logs = load_dataset("player_game_logs")
    newest = pd.NaT
    if logs is not None and not logs.empty and "GameDate" in logs.columns:
        newest = pd.to_datetime(logs["GameDate"], errors="coerce").max()
    age_days = (target - newest.date()).days if pd.notna(newest) else 999
    report: Dict[str, Any] = {
        "Player Logs Before": str(newest.date()) if pd.notna(newest) else "missing",
        "Player Log Age Days": int(age_days),
        "Core Data Refresh": "cache current" if age_days <= 2 else "refresh requested",
    }
    if age_days > 2:
        try:
            raw, debug = download_sportsdataverse_dataset("player_game_logs", [int(target.year)])
            if raw is not None and not raw.empty:
                refreshed = standardize_player_logs(raw)
                if refreshed is not None and not refreshed.empty:
                    combined = pd.concat([logs, refreshed], ignore_index=True, sort=False) if logs is not None and not logs.empty else refreshed
                    combined = standardize_player_logs(combined)
                    save_dataset("player_game_logs", combined)
                    logs = combined
                    newest_after = pd.to_datetime(combined.get("GameDate"), errors="coerce").max()
                    report["Core Data Refresh"] = "player logs updated"
                    report["Player Logs After"] = str(newest_after.date()) if pd.notna(newest_after) else "unknown"
                    try:
                        get_global_datasets.clear()
                    except Exception:
                        pass
            else:
                report["Core Data Refresh"] = "remote unavailable; existing cache preserved"
                if debug is not None and not debug.empty:
                    report["Core Data Detail"] = str(debug.iloc[-1].to_dict())[:300]
        except Exception as exc:
            report["Core Data Refresh"] = f"refresh failed; cache preserved: {str(exc)[:160]}"

    # The historical repository can trail the live season. Fill only the dated
    # gap with final ESPN boxscores before rebuilding recent-form features.
    try:
        logs, espn_report = refresh_incremental_espn_player_logs(logs, target)
        report.update(espn_report)
        try:
            get_global_datasets.clear()
        except Exception:
            pass
    except Exception as exc:
        report["ESPN Gap Refresh"] = f"failed; existing dated logs preserved: {str(exc)[:140]}"
    master = load_dataset("master_features")
    if logs is not None and not logs.empty:
        try:
            master, _ = build_master_features()
            report["Master Features"] = f"rebuilt {len(master)} players"
        except Exception as exc:
            report["Master Features"] = f"existing cache used: {str(exc)[:120]}"
    return logs, master, report


def _projection_only_schedule_context(mode: str, schedule: Optional[pd.DataFrame] = None) -> Dict[str, Dict[str, Any]]:
    """Return verified team/opponent context for a no-line slate.

    This never guesses a matchup. It uses the same schedule cache refreshed by
    the main pipeline and returns an empty mapping when no slate is verified.
    """
    sched = schedule.copy() if schedule is not None and not schedule.empty else schedule_for_slate(mode)
    if sched is None or sched.empty:
        return {}
    away_col = next((c for c in ["Away", "AwayTeam", "Visitor", "VisitorTeam"] if c in sched.columns), None)
    home_col = next((c for c in ["Home", "HomeTeam"] if c in sched.columns), None)
    if not away_col or not home_col:
        return {}
    contexts: Dict[str, Dict[str, Any]] = {}
    for _, game in sched.iterrows():
        away = _team_key_for_matchup(game.get(away_col))
        home = _team_key_for_matchup(game.get(home_col))
        if not away or not home or away == home:
            continue
        game_date = game.get("GameDate", "")
        game_id = str(game.get("GameID", "") or "")
        matchup = f"{away} @ {home}"
        contexts[away] = {
            "Team": away, "Opponent": home, "HomeAway": "AWAY", "Matchup": matchup,
            "Start": game_date, "GameID": game_id,
        }
        contexts[home] = {
            "Team": home, "Opponent": away, "HomeAway": "HOME", "Matchup": matchup,
            "Start": game_date, "GameID": game_id,
        }
    return contexts


def _projection_only_minutes(row: pd.Series) -> float:
    """Conservative minutes estimate for display-only, no-line projections."""
    candidates = [
        ("MinutesProjectionBase", 0.55), ("MIN_l10", 0.25),
        ("MIN_l5", 0.10), ("MIN_l20", 0.05), ("MIN_avg", 0.05),
    ]
    available = [(safe_float(row.get(column), np.nan), weight) for column, weight in candidates]
    available = [(value, weight) for value, weight in available if pd.notna(value) and value > 0]
    if not available:
        return np.nan
    return float(np.clip(sum(value * weight for value, weight in available) / sum(weight for _, weight in available), 0.0, 40.0))


def build_projection_only_board(
    mode: str,
    logs: Optional[pd.DataFrame],
    base: Optional[pd.DataFrame],
    schedule: Optional[pd.DataFrame] = None,
) -> pd.DataFrame:
    """Build scheduled player projections when no sportsbook lines are posted.

    The rows are useful for player/matchup review, but every betting field is
    deliberately unavailable and every row is forced to PASS. No synthetic
    line, edge, probability, or recommendation is created.
    """
    if base is None or base.empty:
        return pd.DataFrame()
    contexts = _projection_only_schedule_context(mode, schedule)
    if not contexts:
        return pd.DataFrame()

    players = base.copy()
    if "NameKey" not in players.columns:
        player_source = players["Player"] if "Player" in players.columns else pd.Series("", index=players.index)
        players["NameKey"] = player_source.map(normalize_name)
    team_source = (
        players["TeamKey"] if "TeamKey" in players.columns
        else players["Team"] if "Team" in players.columns
        else pd.Series("", index=players.index)
    )
    players["_TeamKey"] = team_source.map(_team_key_for_matchup)
    blank_team = players["_TeamKey"].astype(str).str.len().eq(0)
    if blank_team.any() and "Team" in players.columns:
        players.loc[blank_team, "_TeamKey"] = players.loc[blank_team, "Team"].map(_team_key_for_matchup)
    if "Season" in players.columns:
        players["_SeasonNum"] = pd.to_numeric(players["Season"], errors="coerce")
        players = players.sort_values(["NameKey", "_SeasonNum"]).drop_duplicates("NameKey", keep="last")
    else:
        players = players.drop_duplicates("NameKey", keep="last")
    players = players[players["_TeamKey"].isin(contexts)].copy()
    if players.empty:
        return pd.DataFrame()

    players["_ProjectedMinutes"] = players.apply(_projection_only_minutes, axis=1)
    games_source = (
        players["Games"] if "Games" in players.columns
        else players["GP"] if "GP" in players.columns
        else pd.Series(0, index=players.index)
    )
    players["_Games"] = pd.to_numeric(games_source, errors="coerce").fillna(0)
    players = players[players["_ProjectedMinutes"].ge(4.0) & players["_Games"].ge(3)].copy()
    players = players.sort_values(["_TeamKey", "_ProjectedMinutes", "_Games"], ascending=[True, False, False])
    players = players.groupby("_TeamKey", as_index=False, group_keys=False).head(12)
    if players.empty:
        return pd.DataFrame()

    slate_date = str(slate_target_date(mode) or "ALL")
    rows: List[Dict[str, Any]] = []
    for _, player in players.iterrows():
        context = contexts.get(str(player.get("_TeamKey")), {})
        for market in MARKETS:
            rows.append({
                "Player": str(player.get("Player", "") or "").strip(),
                "Matched Player": str(player.get("Player", "") or "").strip(),
                "NameKey": str(player.get("NameKey", "") or ""),
                "Match Score": 1.0,
                "Team": context.get("Team", player.get("_TeamKey", "")),
                "Opponent": context.get("Opponent", ""),
                "HomeAway": context.get("HomeAway", ""),
                "Matchup": context.get("Matchup", ""),
                "Start": context.get("Start", ""),
                "GameID": context.get("GameID", ""),
                "Market": market,
                "Line": np.nan,
                "Line Display": "NO LIVE LINE",
                "Line Status": "UNAVAILABLE",
                "Source": "Projection Only - No Live Line",
                "Board Mode": "PROJECTION_ONLY",
                "Slate": mode,
                "SlateDate": slate_date,
                "MIN Proj": round(float(player.get("_ProjectedMinutes")), 1),
                "L5 Avg": safe_float(player.get(f"{market}_l5"), np.nan),
                "L10 Avg": safe_float(player.get(f"{market}_l10"), np.nan),
                "L20 Avg": safe_float(player.get(f"{market}_l20"), np.nan),
                "Season Avg": safe_float(player.get(f"{market}_avg"), np.nan),
                "PositionGroup": str(player.get("PositionGroup", "Unknown") or "Unknown"),
                "Role Confidence": safe_float(player.get("RoleConfidence"), np.nan),
                "Data Score": safe_float(player.get("DataScore"), np.nan),
                "Projection": np.nan,
            })
    board = pd.DataFrame(rows)
    board = _strict_attach_opponent_context(board, mode)
    board = _strict_market_isolated_rebuild(board, base)
    board = _stable_attach_context_audit_only(board, base)
    board = attach_model_comparison(board, repository=HHSRepository(), simulations=10_000)

    # This final assignment is intentionally after every projection/model layer.
    # A missing line can never become a recommendation through a downstream gate.
    board["Line"] = np.nan
    board["Line Display"] = "NO LIVE LINE"
    board["Line Status"] = "UNAVAILABLE"
    board["Edge"] = np.nan
    board["Mean Edge"] = np.nan
    board["Median Edge"] = np.nan
    board["Over %"] = np.nan
    board["Under %"] = np.nan
    board["MC Over %"] = np.nan
    board["MC Under %"] = np.nan
    board["MC Agreement"] = False
    board["Lean"] = "PASS"
    board["Official"] = "PASS"
    board["Strong Play"] = "TRACK"
    board["Tier"] = "TRACK"
    board["Playable Gate"] = "NO_PLAY"
    board["Projection Readiness"] = "PROJECTION_ONLY"
    board["Projection Missing Inputs"] = "live sportsbook line unavailable"
    board["PASS Reason"] = "No live sportsbook line; projection-only row cannot be wagered or graded."
    board["No-Bet Risk Flags"] = "live sportsbook line unavailable"
    board["Projection Integrity"] = "PROJECTION_ONLY"
    board["Projection Integrity Note"] = "Projection inputs loaded; sportsbook line unavailable."
    board["HHS Direction"] = "PASS"
    board["HHS Over %"] = np.nan
    board["HHS Under %"] = np.nan
    board["HHS Mean Edge"] = np.nan
    board["HHS Median Edge"] = np.nan
    board["HHS Distribution Conflict"] = False
    board["HHS Confidence Tier"] = "PASS"
    board["HHS PASS Reason"] = "No live sportsbook line; HHS distribution is informational only."
    board["Full Live Board Rows"] = 0
    board["Projected Live Rows"] = len(board)
    board["Unprojected Live Rows"] = int(pd.to_numeric(board.get("Projection"), errors="coerce").isna().sum())
    board["Projection Engine Version"] = PROJECTION_ENGINE_VERSION
    board["LineParserVersion"] = LINE_PARSER_VERSION
    return board.reset_index(drop=True)


def run_full_refresh_with_progress(mode: str, use_ud_flag: bool, logs_global: pd.DataFrame, master_global: pd.DataFrame) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    """One visible refresh path: schedule/context, lines, projections, cache."""
    progress = st.progress(0, text="Starting full refresh...")
    status_box = st.empty()
    status: Dict[str, Any] = {"Mode": mode, "Status": "started"}
    started = time.time()

    def step(pct: int, msg: str) -> None:
        progress.progress(pct, text=msg)
        status_box.info(msg)

    try:
        step(8, "Clearing old line pull cache...")
        clear_line_pull_caches()
        st.session_state.pop("wnba_lines_all", None)

        step(20, "Refreshing schedule and team context...")
        sched, sched_dbg = update_schedule_cache_with_espn(mode)
        status["Games"] = 0 if sched is None or sched.empty else len(sched)
        status["Schedule Loaded"] = "YES" if status["Games"] else "NO/CACHED"
        st.session_state["wnba_schedule_debug"] = sched_dbg
        try:
            fetch_underdog_wnba_schedule_feed.clear()
        except Exception:
            pass
        try:
            ml_games, ml_games_dbg = fetch_underdog_wnba_schedule_feed()
            st.session_state["wnba_moneyline_games"] = ml_games
            st.session_state["wnba_moneyline_underdog_debug"] = ml_games_dbg
            status["Moneyline Games"] = 0 if ml_games is None or ml_games.empty else len(ml_games)
            if ml_games is not None and not ml_games.empty:
                UNDERDOG_GAMES_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)
                ml_games.to_csv(UNDERDOG_GAMES_CACHE_FILE, index=False)
                status["Moneyline Source"] = "Underdog full game feed"
            else:
                status["Moneyline Source"] = "no live Underdog games; saved schedule fallback"
        except Exception as exc:
            status["Moneyline Warning"] = str(exc)[:180]
        try:
            game_ctx, game_dbg = build_game_context_cache(mode, force_official=True)
            daily_ctx, daily_dbg = build_daily_team_context_cache_v2(mode, force=True)
            status["Game Context Rows"] = 0 if game_ctx is None or game_ctx.empty else len(game_ctx)
            status["Daily Context Rows"] = 0 if daily_ctx is None or daily_ctx.empty else len(daily_ctx)
            st.session_state["wnba_game_context_debug"] = game_dbg
            st.session_state["wnba_daily_team_context_v2_debug"] = daily_dbg
        except Exception as exc:
            status["Context Warning"] = str(exc)[:160]

        step(32, "Checking authorized HHS advanced-data cache...")
        hhs_report = automatic_hhs_refresh(force=False, blocking=True)
        hhs_coverage = HHSRepository().coverage()
        status["HHS Status"] = ", ".join(sorted(hhs_report.get("Status", pd.Series(dtype=str)).dropna().astype(str).unique().tolist())) if hhs_report is not None and not hhs_report.empty else "unknown"
        status["HHS Datasets"] = f"{hhs_coverage['datasets_available']}/{hhs_coverage['datasets_expected']}"
        status["HHS Rows"] = int(hhs_coverage["rows_loaded"])

        step(38, "Refreshing player logs and rebuilding projection baselines...")
        logs, master, core_report = _refresh_core_projection_data(mode)
        status.update(core_report)
        status["Database Players"] = 0 if master is None or master.empty else len(master)

        step(58, "Pulling current lines...")
        lines_all, ud_debug, manual_debug = pull_board_lines(use_ud_flag, False, False, "")
        lines, slate_note = filter_lines_for_slate(lines_all, mode)
        status["Line Rows"] = 0 if lines is None or lines.empty else len(lines)
        status["Underdog Lines"] = int((lines.get("Source", pd.Series(dtype=str)).astype(str) == "Underdog").sum()) if lines is not None and not lines.empty else 0
        status["Slate Note"] = slate_note
        st.session_state["wnba_ud_debug"] = ud_debug
        st.session_state["wnba_sl_debug"] = manual_debug

        if logs is None or logs.empty or master is None or master.empty:
            status["Status"] = "lines loaded, database missing"
            status["Seconds"] = round(time.time() - started, 2)
            st.session_state["wnba_refresh_today_status"] = status
            step(100, "Refresh finished: lines loaded, but player database is missing.")
            return pd.DataFrame(), status

        if lines is None or lines.empty:
            step(76, "No live player lines are posted; building a projection-only PASS board...")
            board = build_projection_only_board(mode, logs, master, schedule=sched)
            if board is None or board.empty:
                status["Status"] = "no lines and no verified projection-only slate"
                status["Seconds"] = round(time.time() - started, 2)
                st.session_state["wnba_refresh_today_status"] = status
                step(100, "Refresh finished: no live lines and no verified scheduled player slate was available.")
                return pd.DataFrame(), status
            save_dataset("projection_board", board)
            st.session_state[f"wnba_force_live_{mode}"] = False
            st.session_state["wnba_last_refresh"] = now_iso()
            st.session_state["wnba_prefer_projection_cache_after_refresh"] = True
            status["Cards"] = len(board)
            status["Projection Only Rows"] = len(board)
            status["Status"] = "complete_projection_only"
            status["Seconds"] = round(time.time() - started, 2)
            st.session_state["wnba_refresh_today_status"] = status
            step(100, f"Refresh complete: {len(board):,} projection-only rows built. No live line means PASS.")
            return board, status

        step(78, "Building projections from current lines...")
        board = make_projection_board(lines[lines["Market"].isin(MARKETS)], logs, master, mode)
        if board is None or board.empty:
            status["Status"] = "projection build returned 0 rows"
            status["Seconds"] = round(time.time() - started, 2)
            st.session_state["wnba_refresh_today_status"] = status
            step(100, "Refresh finished: projection build returned 0 rows.")
            return pd.DataFrame(), status
        board["Slate"] = mode
        board["SlateDate"] = str(slate_target_date(mode) or "ALL")
        board = enrich_board_with_matchups(board, mode)
        board["Projection Engine Version"] = PROJECTION_ENGINE_VERSION

        step(92, "Saving refreshed board/cache...")
        save_dataset("projection_board", board)
        try:
            save_board_snapshot(board, lines_all, mode)
        except Exception as exc:
            status["Save Snapshot Warning"] = str(exc)[:160]
        st.session_state[f"wnba_force_live_{mode}"] = False
        st.session_state["wnba_last_refresh"] = now_iso()
        st.session_state["wnba_prefer_projection_cache_after_refresh"] = True
        status["Cards"] = len(board)
        status["Status"] = "complete"
        status["Seconds"] = round(time.time() - started, 2)
        st.session_state["wnba_refresh_today_status"] = status
        step(100, f"Refresh complete: {len(board):,} projection rows built.")
        return board, status
    except Exception as exc:
        status["Status"] = f"refresh error: {str(exc)[:180]}"
        status["Seconds"] = round(time.time() - started, 2)
        st.session_state["wnba_refresh_today_status"] = status
        progress.progress(100, text="Refresh stopped with an error.")
        status_box.error(status["Status"])
        return pd.DataFrame(), status


# The queued top refresh is processed after the final make_projection_board
# definition below. Running it here would call an older historical override.


def render_grouped_player_board(mode: str, use_ud_flag: bool, logs_global: pd.DataFrame, master_global: pd.DataFrame):
    """Player Cards synchronized with Best Bets, using one stable projection pass only."""
    st.markdown(f"<div class='section-title'>{mode} — Grouped Player Cards</div>", unsafe_allow_html=True)
    top_cols = st.columns([1.2, 1.0, 1.0, 2.0])
    with top_cols[0]:
        st.info("Use the top REFRESH TODAY button to pull schedule, lines, and projections.")
    with top_cols[1]:
        meta = saved_board_meta()
        st.metric("Last refresh", st.session_state.get("wnba_last_refresh", meta.get("SavedAt", "not yet")))
    with top_cols[2]:
        _cache_preview, _ = _stable_load_or_repair_cached_board(mode, master_global)
        _db_n = 0 if master_global is None or master_global.empty else len(master_global)
        _board_n = 0 if _cache_preview is None or _cache_preview.empty or "Player" not in _cache_preview.columns else int(_cache_preview["Player"].nunique())
        st.metric("Database players" if _db_n > 0 else "Board players", _db_n if _db_n > 0 else _board_n)
    with top_cols[3]:
        st.caption(f"Grouped layout: one player card contains PTS / REB / AST / PRA. Line pull locked: {WORKING_PULL_LOCK}. Projection engine: {PROJECTION_ENGINE_VERSION}.")

    prefer_projection_cache = bool(st.session_state.get("wnba_prefer_projection_cache_after_refresh", False))
    saved_df = load_board_snapshot(mode)
    if not prefer_projection_cache and saved_df is not None and not saved_df.empty:
        saved_df = filter_projection_board_for_slate(saved_df, mode)
        saved_df = _stable_repair_projection_board(saved_df, master_global)
        saved_df.to_csv(CACHE_FILES["projection_board"], index=False)
        st.success("Loaded saved lines and rebuilt them with the stable single-pass projection engine.")
        return _render_grouped_projection_df(saved_df, mode, f"saved_group_search_{mode}", f"saved_group_max_{mode}", f"saved_group_official_only_{mode}", saved_view=True)

    cached_board, cached_label = _stable_load_or_repair_cached_board(mode, master_global)
    cached_board = filter_projection_board_for_slate(cached_board, mode)
    if cached_board is not None and not cached_board.empty:
        if prefer_projection_cache:
            st.session_state["wnba_prefer_projection_cache_after_refresh"] = False
        st.success(f"Loaded {len(cached_board):,} rows from the last-good {cached_label}. Player Cards and Best Bets now use the same repaired board.")
        return _render_grouped_projection_df(cached_board, mode, f"cache_group_search_{mode}", f"cache_group_max_{mode}", f"cache_group_official_only_{mode}", saved_view=True)

    if mode == "Today":
        render_refresh_today_status()
    st.info(f"No cached {mode.lower()} board is available. Nothing was pulled automatically. Use the refresh button to update schedule, lines, and projections.")
    return pd.DataFrame()


